window.SOCIAL_DATA=window.SOCIAL_DATA||[];window.SOCIAL_DATA.push({"id": "geo-3", "subject": "地理", "chapter": "第三章", "title": "中國的人口", "total": 250, "levels": {"必考": 30, "常考": 15}, "mapname": {"g3-map-pop": "中國人口分布圖（黑河—騰衝線）", "g3-map-agri": "中國農牧業分布與等雨量線", "g3-map-sea": "東南亞華人遷移路線圖", "g3-map-pyramid": "中國人口金字塔圖（1980、2020、2040）", "g3-map-sex": "中國歷年新生兒性別比變化統計圖", "g3-map-popstat": "中國人口統計圖"}, "concepts": [{"id": "e8", "name": "人口快速高齡化與政策轉變（全面二孩、三孩政策）", "n": 39, "level": "必考", "card": {"說明": "一胎化政策導致幼年人口比例驟降（少子化），加上現代醫療衛生進步使平均壽命大幅延長，使中國老年人口比例急遽攀升。中國自 2000 年老年人口占比突破 7% 步入高齡化社會，2021 年突破 14% 跨入「高齡社會」，預計 2040 年將達近 30%，面臨「未富先老」挑戰。為挽救青壯年勞動力不足與撫養負擔沈重危機，中國於 2015 年廢止一胎化並開放「全面二孩」，2021 年進一步實施「三孩政策」並搭配教育與育兒補貼。", "關鍵名詞": "<b>高齡社會</b>——依聯合國定義，65 歲以上老年人口占總人口比例達 7% 為「高齡化社會」、達 14% 為「高齡社會」、達 20% 以上則為「超高齡社會」。", "因果／影響": "引發青壯年撫養比驟增、「4-2-1 家庭」（1 名獨生子女需扶養 2 名父母與 4 名祖父母）養老負擔沉重，並造成長期勞動力短缺，迫使國家生育政策全面轉向鼓勵生育。", "出處": "自修第 46–47 頁／講義第 35 頁、速讀秘笈第 3 章。", "標示": "自修重要性評估 ★★★★、會考最新趨勢必考題。"}, "imgs": ["g3-map-pyramid"], "clusters": [{"t": "高齡化原因：一胎化＋醫療進步", "n": 8, "ids": ["g3-75", "g3-135", "g3-186", "g3-187", "g3-236", "g3-242", "g3-105", "g3-209"]}, {"t": "高齡化的影響：扶養比、老人安養", "n": 11, "ids": ["g3-97", "g3-201", "g3-89", "g3-19", "g3-239", "g3-243", "g3-17", "g3-21", "g3-198", "g3-173", "g3-56"]}, {"t": "政策轉向：開放二胎、三孩", "n": 9, "ids": ["g3-63", "g3-109", "g3-217", "g3-194", "g3-146", "g3-216", "g3-51", "g3-247", "g3-22"]}, {"t": "圖表：生育率、普查表、金字塔", "n": 11, "ids": ["g3-12", "g3-106", "g3-210", "g3-26", "g3-104", "g3-145", "g3-207", "g3-215", "g3-96", "g3-190", "g3-192"]}]}, {"id": "e6", "name": "一胎化政策（計畫生育）", "n": 38, "level": "必考", "card": {"說明": "中國人口在清代中葉後快速增長，至 1970 年代面臨嚴峻的人口過多壓力與環境負載瓶頸。為控制人口過快增長，中國政府於 1979 年起嚴格推行計畫生育「一胎化政策」，規定一對夫妻只能生育一個孩子。此政策使人口自然增加率快速由 1980 年的 12‰ 下降至 2020 年的 1‰ 左右，有效抑制了人口暴增。", "關鍵名詞": "<b>一胎化政策</b>——中國政府自 1979 年起強制實施、嚴格規定每對夫婦僅能生育一胎以控制人口成長的計畫生育政策。", "因果／影響": "正面效益為成功減緩人口過快膨脹、減輕環境壓力；但負面代價極其深遠，直接引發了嚴重的「性別比失衡」、「人口少子化」與「快速高齡化」等結構性危機。", "出處": "自修第 45–46 頁／講義第 35 頁、評量單第 6 回。", "標示": "講義「必考重點」、自修 ★★★★。"}, "imgs": ["g3-map-popstat"], "clusters": [{"t": "人口數量龐大（約占世界 1/5）", "n": 10, "ids": ["g3-5", "g3-33", "g3-128", "g3-184", "g3-39", "g3-6", "g3-9", "g3-208", "g3-234", "g3-244"]}, {"t": "一胎化的目的與影響", "n": 15, "ids": ["g3-3", "g3-7", "g3-14", "g3-118", "g3-165", "g3-199", "g3-185", "g3-240", "g3-245", "g3-69", "g3-141", "g3-92", "g3-228", "g3-58", "g3-171"]}, {"t": "基數大，每年仍增加很多人", "n": 7, "ids": ["g3-16", "g3-196", "g3-139", "g3-170", "g3-108", "g3-237", "g3-246"]}, {"t": "圖表：自然增加率、金字塔", "n": 6, "ids": ["g3-31", "g3-49", "g3-53", "g3-71", "g3-70", "g3-107"]}]}, {"id": "e1", "name": "傳統維生方式與因地制宜（東農西牧、南稻北麥）", "n": 38, "level": "必考", "card": {"說明": "中國各地居民為了適應不同的地形與氣候環境，傳統維生方式多因地制宜，其中糧食生產受自然環境限制最大。東部近海地區降水量較多且平原廣闊，農業發達；西部內陸地區因降水較少，除水源豐富的河谷與綠洲有灌溉農業外，傳統多以畜牧維生。東部農業區又以「秦嶺、淮河」為界，北方氣溫較低、降水較少，多旱田並以小麥、高粱為主；南方氣溫較高、降水豐沛，多水田並以水稻為主，形成「南稻北麥」格局。", "關鍵名詞": "<b>因地制宜</b>——人類根據當地自然環境條件（地形、氣候、水文等）的差異，採取最適合當地的生活與生產利用方式。", "因果／影響": "氣候水熱條件的空間差異直接決定了中國「東農西牧」與「南稻北麥」的土地利用結構，進一步奠定了區域人口承載力與聚落分布的基礎。", "出處": "自修第 44 頁／講義第 32 頁、速讀秘笈第 3 章。", "標示": "講義「重點分析」、自修重要性評估 ★★★。"}, "imgs": ["g3-map-agri"], "clusters": [{"t": "東農西牧：年雨量 500mm 線", "n": 13, "ids": ["g3-119", "g3-163", "g3-176", "g3-93", "g3-110", "g3-211", "g3-77", "g3-154", "g3-156", "g3-38", "g3-10", "g3-157", "g3-159"]}, {"t": "南稻北麥：秦嶺、淮河（一月 0℃ 線）", "n": 15, "ids": ["g3-83", "g3-111", "g3-142", "g3-174", "g3-212", "g3-230", "g3-225", "g3-30", "g3-44", "g3-15", "g3-155", "g3-143", "g3-220", "g3-11", "g3-62"]}, {"t": "西部農業靠綠洲、河谷的水源", "n": 6, "ids": ["g3-54", "g3-137", "g3-160", "g3-183", "g3-175", "g3-95"]}, {"t": "東部農業條件與少數民族", "n": 4, "ids": ["g3-73", "g3-43", "g3-235", "g3-144"]}]}, {"id": "e5", "name": "人口遷移與文化擴散（東南沿海外移、下南洋）", "n": 33, "level": "必考", "card": {"說明": "中國因人口眾多且分布不均，為了尋求更多耕地或工作機會，歷代常出現國內或海外的人口遷移。明清時期，東南沿海（如福建、廣東）因「山多平原少、耕地不足」，加上人口急速增加導致糧食匱乏，促使大批居民冒險移居臺灣或東南亞（南洋）開墾經商。移民將原鄉的生活習俗、飲食習慣（如肉骨茶、潮州菜）、宗教信仰（如媽祖信仰）及文字帶到移居地，此現象稱為「文化擴散」。", "關鍵名詞": "• <b>文化擴散</b>：移民將原鄉的文化特質（語言、信仰、生活習慣）傳播至新移居地區的過程。<br>• <b>下南洋</b>：明清以來中國東南沿海居民大規模橫渡南海、遷徙至東南亞謀生發展的歷史移民潮。", "因果／影響": "造就了東南亞各地繁榮的唐人街與華人社群，使中華文化深植於南洋社會。", "出處": "自修第 45 頁／講義第 34 頁。", "標示": "自修重要性評估 ★★★★、會考生活跨科精熟題。"}, "imgs": ["g3-map-sea"], "clusters": [{"t": "文化擴散的意義與例子", "n": 14, "ids": ["g3-24", "g3-59", "g3-81", "g3-180", "g3-223", "g3-2", "g3-226", "g3-233", "g3-125", "g3-76", "g3-103", "g3-131", "g3-55", "g3-86"]}, {"t": "明清閩粵移民：臺灣與東南亞", "n": 11, "ids": ["g3-78", "g3-115", "g3-126", "g3-136", "g3-164", "g3-168", "g3-182", "g3-189", "g3-179", "g3-60", "g3-231"]}, {"t": "外移原因：山多平原少、人口增加", "n": 7, "ids": ["g3-61", "g3-85", "g3-123", "g3-193", "g3-27", "g3-74", "g3-132"]}, {"t": "冬季東北季風南下", "n": 1, "ids": ["g3-23"]}]}, {"id": "e3", "name": "人口分布分界線（黑河—騰衝線）", "n": 32, "level": "必考", "card": {"說明": "中國受地形與氣候條件交互影響，人口分布呈現極度不均的「東稠西稀」特徵。地理學家胡煥庸提出以黑龍江省「黑河」至雲南省「騰衝」畫一直線，將全國劃分為東半部與西半部。東半部面積僅占全國 43%，卻聚集了約 94% 的人口；西半部面積廣達 57%，人口卻僅占約 6%。", "關鍵名詞": "<b>黑河—騰衝線</b>——連接黑龍江省黑河市與雲南省騰衝市的假想直線，為中國劃分人口疏密與自然經濟環境懸殊的關鍵分界線。", "因果／影響": "東半部因平原廣、氣候溫潤、農業與工商業發達，形成高密度的人口精華區；西半部則因高原山地廣布且乾旱少雨，環境承載力低，人口稀疏且僅集中於有水源的河谷與綠洲。", "出處": "自修第 44 頁／講義第 33–34 頁、速讀秘笈第 3 章。", "標示": "自修重要性評估 ★★★★、會考高頻必考題。"}, "imgs": ["g3-map-pop"], "clusters": [{"t": "認出黑河—騰衝線", "n": 11, "ids": ["g3-32", "g3-114", "g3-169", "g3-124", "g3-148", "g3-28", "g3-84", "g3-65", "g3-113", "g3-153", "g3-222"]}, {"t": "東 43%／94%、西 57%／6%", "n": 5, "ids": ["g3-4", "g3-181", "g3-218", "g3-102", "g3-45"]}, {"t": "人口疏密的原因：地形與氣候", "n": 7, "ids": ["g3-221", "g3-82", "g3-91", "g3-224", "g3-13", "g3-161", "g3-122"]}, {"t": "生活中的疏密現象（春運、疫情、地價）", "n": 9, "ids": ["g3-101", "g3-151", "g3-90", "g3-202", "g3-35", "g3-66", "g3-191", "g3-219", "g3-214"]}]}, {"id": "e7", "name": "人口性別比失衡與光棍問題", "n": 24, "level": "常考", "card": {"說明": "中國社會傳統深具「重男輕女」與「傳宗接代」的觀念，在一胎化政策限制下，多數家庭普遍希望唯一的孩子是男孩，造成人工性別篩選猖獗，新生兒性別比嚴重偏離正常範圍（正常值約 102～107）。2024 年中國新生兒性別比高達 109（每 100 名女嬰對應 109 名男嬰），成年後造成數千萬男性面臨適婚年齡難以婚配的「光棍」現象與社會動盪。", "關鍵名詞": "<b>性別比</b>——每 100 名女性所對應的男性人口比例（計算公式為：$\\frac{\\text{男性人口}}{\\text{女性人口}} \\times 100$），數值大於 100 代表男多於女。", "因果／影響": "衍生出「光棍村」、婚姻擠壓、跨國人口販運（如非法緬甸新娘）等諸多社會隱憂；政府遂積極倡導「女孩男孩一樣好」觀念進行宣導改善。", "出處": "自修第 46 頁／講義第 35 頁。", "標示": "講義「重點分析」、時事素養必考題。"}, "imgs": ["g3-map-sex"], "clusters": [{"t": "性別比的意義與計算", "n": 9, "ids": ["g3-166", "g3-248", "g3-18", "g3-64", "g3-203", "g3-130", "g3-37", "g3-48", "g3-150"]}, {"t": "原因：重男輕女＋一胎化", "n": 8, "ids": ["g3-36", "g3-47", "g3-117", "g3-195", "g3-149", "g3-200", "g3-249", "g3-250"]}, {"t": "影響與對策：光棍、買新娘、宣導", "n": 5, "ids": ["g3-98", "g3-204", "g3-72", "g3-127", "g3-80"]}, {"t": "新生兒性別比圖", "n": 2, "ids": ["g3-79", "g3-241"]}]}, {"id": "e2", "name": "西部畜牧業的三大類型（放牧、游牧、山牧季移）", "n": 19, "level": "常考", "card": {"說明": "西部乾燥與高寒地區受水草豐歉及地形垂直變化影響，發展出三種不同的畜牧方式。水草較豐富的內蒙古高原東側以定居式的「放牧」為主；氣候乾旱的新疆沙漠邊緣與內蒙古高原西側，牧民驅趕牲畜「逐水草而居」，形成「游牧」；青藏高原與天山等高山地區，牧民順應氣溫與草料的垂直季節變化，「春天上山放牧（吃草）、秋天下山避冬」，稱為「山牧季移」。", "關鍵名詞": "<b>山牧季移</b>——高山與高原地區牧民順應隨海拔高度變化的氣溫與牧草生長季，春天驅趕牲畜上山、秋天下山避冬的垂直季節性畜牧方式。", "因果／影響": "使脆弱的高山與草原生態環境獲得休養生息，滿足牧民生存需求，犛牛與羊群成為藏族與哈薩克族等高原民族的核心生活資產。", "出處": "自修第 44 頁／講義第 32 頁。", "標示": "講義「重點分析」、會考經典題型。"}, "imgs": ["g3-map-agri"], "clusters": [{"t": "山牧季移：高原高山、春上秋下", "n": 10, "ids": ["g3-40", "g3-42", "g3-112", "g3-120", "g3-140", "g3-162", "g3-177", "g3-206", "g3-213", "g3-100"]}, {"t": "游牧：逐水草而居", "n": 3, "ids": ["g3-87", "g3-229", "g3-25"]}, {"t": "放牧 vs 游牧：降水多寡", "n": 3, "ids": ["g3-41", "g3-50", "g3-158"]}, {"t": "游牧 vs 山牧季移：地勢高低", "n": 3, "ids": ["g3-94", "g3-121", "g3-178"]}]}, {"id": "e4", "name": "環境負載力", "n": 14, "level": "一般", "card": {"說明": "環境負載力是指一個生活環境系統所能供養生物（或人口）數量的最大極限能力，以及其吸收與分解廢棄物的能力。一地環境負載力的高低受自然資源、生產技術與經濟發展程度影響；當人口數量超過環境負載力時，將造成資源短缺、生態破壞與就業不足，反之透過農業科技進步則可適度提升負載力。", "關鍵名詞": "<b>環境負載力</b>——指一地生活環境在維持生態平衡下，所能持續供養的最多人口數量與承受干擾的能力。", "因果／影響": "中國東部平原地帶水土資源豐沛、環境負載力高，故能生養眾多人口；西部高原與乾旱區生態脆弱、負載力極低，過度開發易引發荒漠化與生態危機。", "出處": "自修第 45 頁／講義第 35、40 頁。", "標示": "講義「延伸學習／重點」、易錯觀念題。"}, "imgs": [], "clusters": [{"t": "環境負載力高的地區", "n": 6, "ids": ["g3-129", "g3-138", "g3-116", "g3-167", "g3-88", "g3-52"]}, {"t": "環境負載力低的地區", "n": 3, "ids": ["g3-67", "g3-238", "g3-232"]}, {"t": "東高西低與人口疏密", "n": 2, "ids": ["g3-99", "g3-197"]}, {"t": "人口太多、糧食不足", "n": 3, "ids": ["g3-8", "g3-20", "g3-227"]}]}, {"id": "e9", "name": "人口紅利消退與勞動力短缺", "n": 13, "level": "一般", "card": {"說明": "過去中國憑藉龐大的壯年勞動力（15～64 歲）人口優勢，提供充沛廉價的勞工並創造廣大內需消費市場，吸引跨國企業投資設廠，奠定經濟崛起的重要基石，稱為「人口紅利」。然而隨著長年少子化與高齡化發酵，壯年勞動人口比例自 2010 年高峰（約 74.5%）逐步下降，未來的勞動力將面臨不足，扶養負擔反向大增。", "關鍵名詞": "<b>人口紅利</b>——指一國勞動年齡人口（壯年人口）占總人口比重極高、撫養比較低，為經濟成長創造充沛勞力與高儲蓄率的黃金人口結構時期。", "因果／影響": "廉價勞工優勢逐步消失，國內基本工資上漲，迫使製造業外移或加速推動工業自動化與產業升級。", "出處": "自修第 45、47 頁／講義第 35、37 頁。", "標示": "講義「會考精熟題」、自修「重點整合」。"}, "imgs": ["g3-map-pyramid"], "clusters": [{"t": "勞動力短缺 → 結束一胎化", "n": 4, "ids": ["g3-29", "g3-34", "g3-68", "g3-188"]}, {"t": "扶養比先降後升", "n": 4, "ids": ["g3-57", "g3-134", "g3-172", "g3-1"]}, {"t": "人口多：市場大、勞力多", "n": 2, "ids": ["g3-133", "g3-46"]}, {"t": "壯年人口移入大都市", "n": 3, "ids": ["g3-147", "g3-205", "g3-152"]}]}], "questions": [{"id": "g3-1", "no": 1, "c": "e9", "src": "114上翰林社會2上A卷 卷4 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(一)是中國 1970 年代人口特徵的描繪，由圖可知其人口結構的特色為何？", "o": ["性別比失衡", "人口大量外移", "人力資源豐富", "人口扶養比高"], "a": 3, "e": "漫畫中一個壯年人扛著一大群老人和小孩，表示「被扶養的人很多」，也就是扶養比高。", "rep": false, "img": "g3-q1", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-2", "no": 2, "c": "e5", "src": "114上翰林社會2上A卷 卷4 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "蒲田餐廳創辦人來自福建，多年前移居新加坡，憑藉推廣道地家鄉菜的思念，2000 年在新加坡開了首家蒲田餐廳。由上述內容可知，下列敘述何者正確？", "o": ["人口遷移及文化擴散", "現代農業的轉型策略", "人口生育政策所導致", "氣候農業而促使外移"], "a": 0, "e": "福建人移居新加坡，把家鄉菜帶過去開餐廳，就是人口遷移帶來的文化擴散。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-3", "no": 3, "c": "e6", "src": "114上翰林社會2上A卷 卷4 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "1954 年以前中國的人口約為 6 億，1980 年時已高達 10 億，但從 1980 年後中國人口成長速度逐漸趨緩。1980 年後中國人口趨緩的主因為何？", "o": ["社會增加率上升", "自然增加率上升", "社會增加率下降", "自然增加率下降"], "a": 3, "e": "1980 年前後中國推行一胎化，出生率下降，使自然增加率下降，人口成長才變慢。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-4", "no": 4, "c": "e3", "src": "114上翰林社會2上A卷 卷4 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國西部區域面積約占 57%，人口卻只有 6%，這呈現出西半部的哪一種人口特色？", "o": ["人口出生率低", "社會增加較少", "人口密度較低", "人口素質不均"], "a": 2, "e": "西半部面積大（57%）人口少（6%），代表人口密度低。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-5", "no": 5, "c": "e6", "src": "114上翰林社會2上A卷 卷4 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "目前全球人口已突破 75 億人。曉玲想利用圓餅圖繪製中國與全球人口比例的關係，灰色區塊表示中國人口比例，則下列哪一張圖最接近現況？", "o": ["灰色占 5%", "灰色占 10%", "灰色占 20%", "灰色占 33%"], "a": 2, "e": "中國人口約 14 億，全球約 75～80 億，中國約占 1/5，也就是 20% 左右。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-6", "no": 6, "c": "e6", "src": "114上翰林社會2上A卷 卷4 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國的身分證在原先 15 碼（住址碼＋出生年月日）後面新增順序碼（性別）與校驗碼，以解決原 15 碼相同的問題。此政策的調整與下列何者關係最密切？", "o": ["移入率的上升", "人口逐漸老化", "教育程度提高", "人口數量眾多"], "a": 3, "e": "人口太多，原本 15 碼容易重複，才要加碼，和人口數量眾多有關。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-7", "no": 7, "c": "e6", "src": "114上翰林社會2上A卷 卷4 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國傳統觀念認為多子多孫多福氣，如今卻出現小皇帝、小公主的現象，這是因為政府人口政策干預下的結果。下列何者最能說明此政策後的現象？", "o": ["社會增加率隨時間上升", "出生率隨時間上升", "人口數隨時間下降", "自然增加率隨時間下降"], "a": 3, "e": "一胎化使出生率下降，自然增加率隨時間下降，獨生子女被寵成小皇帝、小公主。", "rep": false, "img": "g3-q7", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-8", "no": 8, "c": "e4", "src": "114上翰林社會2上A卷 卷4 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國物產豐富，但國內生產的糧食仍然供應不足，每年必須依靠國外大量進口才能滿足需求。造成上述中國糧食不足的主要原因為何？", "o": ["水、旱災頻繁", "人口數量太多", "食物保存不易", "飲食習慣改變"], "a": 1, "e": "人口數量太多，國內生產的糧食不夠吃，只好大量進口。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-9", "no": 9, "c": "e6", "src": "114上翰林社會2上A卷 卷4 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "近年中國許多大都市的教育機構，開設幼童 MBA 課程，主要在啟發幼童的思考力及創造力。中國許多父母擔憂孩子未來就業競爭激烈，主要源自於中國人口的何種特色？", "o": ["人口數量龐大", "人口結構失衡", "人口素質不均", "勞動力不足"], "a": 0, "e": "人口數量龐大，升學、就業競爭激烈，父母才會從小讓孩子補習。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-10", "no": 10, "c": "e1", "src": "114上翰林社會2上A卷 卷4 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國人口分布不均，以黑河與騰衝兩地連線為界，西半部人口稀疏，大多集中在少數的綠洲和河谷。下列哪一種維生方式在西半部最不常見？", "o": ["游牧", "放牧", "水稻耕作", "山牧季移"], "a": 2, "e": "西半部乾燥少雨，以畜牧為主；水稻需要大量的水，在西半部最不常見。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-11", "no": 11, "c": "e1", "src": "114上翰林社會2上A卷 卷4 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "習羽很喜歡吃麵食，依小麥的生長環境判斷，他應該前往下列中國哪個氣候圖的城市，才能吃到以當地大量出產的小麥所做出的道地麵食料理？", "o": ["氣候圖 (A)", "氣候圖 (B)", "氣候圖 (C)", "氣候圖 (D)"], "a": 2, "e": "小麥種在秦嶺、淮河以北的旱田區：冬季氣溫低於 0℃、年雨量較少（約 500～750mm），對照氣候圖要選 (C)。", "rep": false, "img": "g3-q11", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-12", "no": 12, "c": "e8", "src": "114上翰林社會2上A卷 卷4 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "一般而言，生育率低於 1.5 就稱為「超低生育率」。圖(二)為中國生育率統計圖，可知中國在哪一年出現此現象？", "o": ["1980 年", "1990 年", "1995 年", "2000 年"], "a": 3, "e": "生育率在 2000 年已降到 1.5 以下（約 1.2），所以是 2000 年開始出現超低生育率。", "rep": true, "img": "g3-q12", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-13", "no": 13, "c": "e3", "src": "114上翰林社會2上A卷 卷4 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(三)為中國人口分布圖，圖中甲、乙連線以西的地區，其聚落形成的先決條件往往與下列哪個因素有關？", "o": ["政府開發新市鎮", "礦產資源豐富", "鐵、公路經過", "水源取得方便"], "a": 3, "e": "黑河—騰衝線以西乾燥少雨，人口集中在有水源的綠洲、河谷，所以水源是聚落形成的先決條件。", "rep": false, "img": "g3-q13", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-14", "no": 14, "c": "e6", "src": "114上翰林社會2上A卷 卷4 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(四)為中國人口政策宣傳漫畫。此文宣的目的，是希望中國人口數量產生何種變化？", "o": ["出生率降低", "死亡率增加", "移入率減少", "移出率增加"], "a": 0, "e": "「還不清的兒孫債」諷刺孩子生太多，宣導目的是少生，讓出生率降低。", "rep": false, "img": "g3-q14", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-15", "no": 15, "c": "e1", "src": "114上翰林社會2上A卷 卷4 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "宗國在暑假到中國旅遊，預計沿著海岸線由南方北方前進，在越過圖(五)中甲河段時，最可能出現下列哪一景觀？", "o": ["黃澄澄麥田隨風搖曳", "牛羊成群隨水源遷徙", "翠綠稻田翻滾如水波", "牧人驅牛羊到高山放牧"], "a": 0, "e": "由南往北越過秦嶺、淮河一帶後進入旱田區，會看到金黃的麥田。", "rep": true, "img": "g3-q15", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-16", "no": 16, "c": "e6", "src": "114上翰林社會2上A卷 卷4 第 16 題", "st": "考卷", "ctx": "", "fig": "表：出生率／死亡率／人口增加率（‰）／人口增加數（千人）——甲 12.2／6.9／5／6,650；乙 13.8／8.4／8／2,474；丙 17.3／6.0／11／985；丁 29.4／4.9／24／712", "q": "附表是明哲蒐集部分國家 2019 年的人口資料。表中甲國的人口增加數明顯大於其他國家，推論其原因，下列何者最合理？", "o": ["醫療條件較為優越", "移入率大於移出率", "施行獎勵生育政策", "人口總數較為龐大"], "a": 3, "e": "甲國自然增加率只有 5‰，但增加的人口最多，是因為它原本人口總數就非常龐大。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-17", "no": 17, "c": "e8", "src": "114上翰林社會2上A卷 卷4 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(六)為中國各省 65 歲以上人口比例，可知目前中國人口面臨何種困境？", "o": ["人口分布不均", "醫藥衛生退步", "人口老化嚴重", "男女比例失衡"], "a": 2, "e": "圖中多數省分 65 歲以上人口比例超過 7%，甚至超過 14%，表示人口老化嚴重。", "rep": false, "img": "g3-q17", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-18", "no": 18, "c": "e7", "src": "114上翰林社會2上A卷 卷4 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國超單身時代來臨，資料顯示 2024 年中國未婚人口數達 3 億人。其中大城市男女比例失衡為原因之一，北京、上海、深圳、廈門等城市普遍都是女性多於男性。上述城市的人口組成有何特徵？", "o": ["出生率增加", "移入率減少", "扶養比增加", "性別比降低"], "a": 3, "e": "性別比＝男÷女×100，城市中女性多於男性，性別比就會降低（小於 100）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-19", "no": 19, "c": "e8", "src": "114上翰林社會2上A卷 卷4 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(七)為中國三個時期的人口金字塔圖，由圖片內容判斷，中國未來人口可能面臨下列何項人口問題？", "o": ["人口呈現負成長", "高齡人口數下降", "勞動力人口增加", "扶養比負擔沉重"], "a": 3, "e": "由 1980 到 2040 年，幼年人口減少、老年人口增加，未來扶養比負擔沉重。", "rep": false, "img": "g3-q19", "imgnote": "", "fh": "", "maps": ["g3-map-pyramid"], "chk": ""}, {"id": "g3-20", "no": 20, "c": "e4", "src": "114上翰林社會2上A卷 卷4 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(八)為中國近年糧食進口金額統計，可知中國在糧食供應面臨何種現況？", "o": ["人口分布不均", "糧食供應不足", "多以畜牧維生", "人口遷移嚴重"], "a": 1, "e": "糧食進口金額逐年攀升，代表國內糧食供應不足。", "rep": false, "img": "g3-q20", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-21", "no": 21, "c": "e8", "src": "114上翰林社會2上A卷 卷4 題組 (一) 1", "st": "考卷", "ctx": "", "fig": "", "q": "養老機器人是中國近年興起的新興產業，圖(九)顯示該產業在各地的養老分布現況。數量較多的地區除了具備良好的產業條件外，當地對養老機器人的需求也較高。從市場需求探討該產業的分布特色，何者正確？", "o": ["內陸地區老年人口多，市場需求較低", "東部沿海老年人口多，市場需求較高", "內陸地區老年人口少，市場需求較高", "東部沿海老年人口少，市場需求較低"], "a": 1, "e": "養老機器人集中在東部沿海，因為那裡老年人口多，市場需求較高。", "rep": false, "img": "g3-q21", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-22", "no": 22, "c": "e8", "src": "114上翰林社會2上A卷 卷4 題組 (一) 2", "st": "考卷", "ctx": "養老機器人是中國近年興起的新興產業，圖(九)顯示該產業在各地的養老分布現況。數量較多的地區除了具備良好的產業條件外，當地對養老機器人的需求也較高。", "fig": "", "q": "承上題，由圖(九)可知東部沿海地區應推動哪項政策來應對？", "o": ["提升內陸地區環境負載力", "鼓勵壯年遷居至海外發展", "獎勵育有三孩以上之家庭", "推廣性別平等的養育觀念"], "a": 2, "e": "東部沿海老年人口多，要獎勵生育（例如獎勵生三孩），增加未來的勞動人口。", "rep": false, "img": "g3-q21", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-23", "no": 23, "c": "e5", "src": "114上翰林社會2上A卷 卷4 題組 (二) 1", "st": "考卷", "ctx": "", "fig": "", "q": "圖(十)為中國華人遷移的示意圖，華人的生活習慣隨著人口遷移傳播到東南亞等國。若想從中國一路順風到東南亞，最好選在何時出發？", "o": ["春季", "夏季", "秋季", "冬季"], "a": 3, "e": "冬季吹東北季風，帆船可以從中國東南沿海順風南下到東南亞。", "rep": true, "img": "g3-q23", "imgnote": "", "fh": "", "maps": ["g3-map-sea"], "chk": ""}, {"id": "g3-24", "no": 24, "c": "e5", "src": "114上翰林社會2上A卷 卷4 題組 (二) 2", "st": "考卷", "ctx": "", "fig": "", "q": "下列哪一名詞能解釋華人將生活習慣傳播到東南亞等國的現象？", "o": ["人口遷移", "社會增加", "文化擴散", "人口分布"], "a": 2, "e": "把原鄉的生活習慣帶到移居地，稱為文化擴散。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-25", "no": 25, "c": "e2", "src": "114上翰林社會2上A卷 卷4 實戰模擬題 1", "st": "考卷", "ctx": "", "fig": "", "q": "新疆阿勒泰地區的牧民，每年在氣溫回升的春季會進行轉場，將牲畜從由飼料補給的冬牧場，遷徙到數百公里遠的春秋牧場，合理利用牧草資源，以維護當地脆弱的生態體系。造成這種轉場現象的主要原因為下列何者？", "o": ["冬季氣溫嚴寒，積雪覆蓋", "夏季極端高溫，草場乾枯", "降水時間不均，春夏乾旱", "年溫差起伏小，降水充足"], "a": 0, "e": "春季氣溫回升前，冬季嚴寒、積雪覆蓋，牧民只能靠飼料；回暖後才轉場到春秋牧場。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-26", "no": 26, "c": "e8", "src": "114上翰林社會2上A卷 卷4 實戰模擬題 2", "st": "考卷", "ctx": "", "fig": "", "q": "生育率低於 1.5 時，稱為「超低生育率」，即每一位育齡婦女（15～49 歲）平均只生 1.5 個小孩，而 0～14 歲人口比例低於 18% 時，即視為「嚴重少子化」。若要佐證中國面臨超低生育率及嚴重少子化問題，應蒐集下列哪些資料？ (甲)勞動力人口數 (乙)新生兒性別比 (丙)幼年人口比例 (丁)該年出生率", "o": ["甲乙", "乙丙", "丙丁", "甲丁"], "a": 2, "e": "超低生育率要看出生率（丁），嚴重少子化要看幼年人口比例（丙）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-27", "no": 27, "c": "e5", "src": "114上翰林社會2上A卷 卷4 實戰模擬題 3", "st": "考卷", "ctx": "", "fig": "", "q": "檳城是馬來西亞華人分布比例最高的城市，鄭和、孫中山等歷史名人都曾在這裡留下足跡，城市中隨處可見宗祠和廟宇、住宅門楣的籍貫圓牌等中國元素。上述城市華人的祖先最主要來自中國哪一地形區？", "o": ["東北平原", "青藏高原", "四川盆地", "東南丘陵"], "a": 3, "e": "東南亞華人祖先多來自山多平原少的閩粵一帶，也就是東南丘陵。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-sea"], "chk": ""}, {"id": "g3-28", "no": 28, "c": "e3", "src": "114上翰林社會2上A卷 卷4 實戰模擬題 4", "st": "考卷", "ctx": "", "fig": "", "q": "中國因區域遼闊，自然與人文景觀呈現多樣變化。圖(十一)中的虛線大致是以中國哪一種地理現象為分界線？", "o": ["水田與旱田", "草原與沙漠氣候區", "年降水量 750 mm 分界", "人口稀疏與稠密區"], "a": 3, "e": "圖中虛線是黑河—騰衝線，是人口稀疏區與稠密區的分界。", "rep": false, "img": "g3-q28", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-29", "no": 29, "c": "e9", "src": "114上翰林社會2上A卷 卷4 實戰模擬題 5", "st": "考卷", "ctx": "", "fig": "", "q": "中國政府於 1979 年起實施「一胎化政策」，於 2015 年宣告結束。此種政策的轉變，是中國政府為了預防未來哪個問題的發生？", "o": ["人口分布不均", "人口素質降低", "人力資源短缺", "失業人口增加"], "a": 2, "e": "一胎化結束是因為少子化、高齡化，擔心未來勞動力（人力資源）短缺。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-30", "no": 30, "c": "e1", "src": "114上翰林社會2上A卷 卷4 實戰模擬題 6", "st": "考卷", "ctx": "", "fig": "", "q": "圖(十二)為某學者根據自然和人文的綜合數據所繪製出，此分界帶與下列何者最有關？", "o": ["農業區與畜牧區", "游牧區與放牧區", "季風區與乾燥區", "多旱田與多水田"], "a": 3, "e": "這條分界帶在秦嶺、淮河一帶，北邊多旱田、南邊多水田。", "rep": false, "img": "g3-q30", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-31", "no": 31, "c": "e6", "src": "114上翰林社會2上A卷 卷4 實戰模擬題 7", "st": "考卷", "ctx": "", "fig": "", "q": "圖(十三)為中國人口統計圖（含預估），造成此趨勢的原因最可能為下列何者？", "o": ["人口增加率為正", "社會增加率上升", "自然增加率下降", "人口性別比上升"], "a": 2, "e": "出生率持續下降，使自然增加率下降，甚至變成負值，人口總數開始減少。", "rep": true, "img": "g3-q31", "imgnote": "", "fh": "", "maps": ["g3-map-popstat"], "chk": ""}, {"id": "g3-32", "no": 32, "c": "e3", "src": "114上翰林社會2上B卷 卷4 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國的人口分布有明顯的空間差異，下列哪兩個城市連線的兩側有明顯的人口分布差異？", "o": ["黃河—昆明", "黑河—騰衝", "黃河—海口", "黑河—昆明"], "a": 1, "e": "黑河—騰衝線兩側人口分布差異最明顯。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-33", "no": 33, "c": "e6", "src": "114上翰林社會2上B卷 卷4 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "如果利用圓餅圖來繪製中國人口占世界總人口的比例，則下列哪一張圖所呈現的內容最接近現況？", "o": ["5%", "10%", "20%", "33%"], "a": 2, "e": "中國人口約占世界的 1/5，約 20%。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-34", "no": 34, "c": "e9", "src": "114上翰林社會2上B卷 卷4 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "2015 年 10 月，中國宣布結束一胎化政策，並鼓勵夫妻可以生育兩個子女。中國廢除此政策的主要目的，是擔憂會導致下列哪一問題？", "o": ["就業機會不足", "貧富差距擴大", "勞動力的不足", "人口素質不均"], "a": 2, "e": "廢除一胎化是擔心少子化、高齡化，造成勞動力不足。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-35", "no": 35, "c": "e3", "src": "114上翰林社會2上B卷 卷4 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "根據統計結果顯示，地價的高低與當地人口密度呈現明顯的正相關。若臺灣某房屋仲介業者計畫到中國拓展店點，並希望成交金額及成交量可以較高，則下列哪一地區最不可能成為該公司的拓點位置？", "o": ["華北平原", "四川盆地", "青藏高原", "長江三角洲"], "a": 2, "e": "青藏高原地勢高、氣候寒冷，人口密度低，地價也低，最不適合拓點。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-36", "no": 36, "c": "e7", "src": "114上翰林社會2上B卷 卷4 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "國家的傳統觀念會影響到人口的結構，若要用圖示呈現出中國社會的傳統觀念，下列哪一張圖較適當？", "o": ["「重男」較重、「輕女」較輕的天秤", "「輕男」較輕、「重女」較重的天秤", "「男女平等」的天秤", "「不婚不生」的天秤"], "a": 0, "e": "傳統「重男輕女」觀念，用天秤表示就是「重男」那邊較重、「輕女」那邊較輕，選 (A)。", "rep": false, "img": "g3-q36", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-37", "no": 37, "c": "e7", "src": "114上翰林社會2上B卷 卷4 第 6 題", "st": "考卷", "ctx": "", "fig": "圖(一)為男性持花求婚卻因僧多粥少無奈哭泣的漫畫", "q": "圖(一)所呈現的是中國的某種人口現象，依據圖中資訊判斷，中國的性別比數值最可能為下列何者？「嫁給我吧！娶不到老婆」", "o": ["50", "98", "100", "109"], "a": 3, "e": "漫畫中很多男人搶著向一位女性求婚，表示男多於女，性別比大於 100，最接近 109。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-38", "no": 38, "c": "e1", "src": "114上翰林社會2上B卷 卷4 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "「中國東半部地區的居民以米、麥為主食，而西半部地區則以肉、乳為主食。」影響上述人文景觀出現明顯空間差異的主要原因為何？", "o": ["地形起伏不一", "氣候環境不同", "宗教信仰差異", "政治環境不同"], "a": 1, "e": "東部溼潤適合農業（米、麥），西部乾燥以畜牧（肉、乳）為主，主因是氣候環境不同。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-39", "no": 39, "c": "e6", "src": "114上翰林社會2上B卷 卷4 第 8 題", "st": "考卷", "ctx": "", "fig": "表(一)：全球前四大國家人口數——甲 14.35 億、乙 14.08 億、丙 3.41 億、丁 2.81 億", "q": "表(一)是截至 2025 年 2 月 1 日全球前四大國家人口數，何者最可能是中國的人口資料？", "o": ["甲", "乙", "丙", "丁"], "a": 1, "e": "2025 年印度人口已超過中國，第一名甲是印度，中國是第二名乙（14.08 億）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-40", "no": 40, "c": "e2", "src": "114上翰林社會2上B卷 卷4 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國各地的居民為了適應不同的地形與氣候，傳統維生方式通常因地制宜。下列哪一個地區的民眾最可能會採用山牧季移的方式？", "o": ["青藏高原", "東北平原", "四川盆地", "東南丘陵"], "a": 0, "e": "山牧季移出現在高山、高原地區，例如青藏高原。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-41", "no": 41, "c": "e2", "src": "114上翰林社會2上B卷 卷4 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "內蒙古自治區是中國畜牧業重鎮，在該行政區東側多採放牧，西側則以游牧為主。影響兩地畜牧方式差異的主要原因最可能為下列何者？", "o": ["降水多寡", "地勢高低", "技術優劣", "人口密度"], "a": 0, "e": "內蒙古東側降水較多、水草豐富，可以放牧；西側較乾，只能逐水草游牧，主因是降水多寡。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-42", "no": 42, "c": "e2", "src": "114上翰林社會2上B卷 卷4 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國的傳統維生方式有明顯的空間差異，其中青藏高原一帶的居民之傳統維生方式最可能為下列何者？", "o": ["以游牧飼養駱駝", "旱田內種植小麥", "水田內種植水稻", "山牧季移飼養犛牛"], "a": 3, "e": "青藏高原以山牧季移為主，飼養耐寒的犛牛。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-43", "no": 43, "c": "e1", "src": "114上翰林社會2上B卷 卷4 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(二)為中國四個少數民族自治區的位置。何者是以農業為主要維生方式？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "丁在中國南方（廣西），位於東部季風區，以農業為主；甲乙丙在西部，多畜牧。", "rep": false, "img": "g3-q43", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-44", "no": 44, "c": "e1", "src": "114上翰林社會2上B卷 卷4 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "秦嶺、淮河是一條具有多重歷史意義的地理分界線，如果前往該界線以南地區旅遊，最可能在該地區的農田見到下列哪一種大規模的景觀？", "o": ["低垂的金黃麥穗", "嫩綠的水稻秧苗", "結實纍纍的高粱", "高聳筆挺的玉米"], "a": 1, "e": "秦嶺、淮河以南為水田區，可以看到嫩綠的水稻秧苗。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-45", "no": 45, "c": "e3", "src": "114上翰林社會2上B卷 卷4 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(三)是中國傳統農牧業的分界，下列關於圖中甲、乙兩區的人口分布之描述何者正確？", "o": ["甲、乙兩區人口數均多且密度高", "甲、乙兩區人口數均少且密度低", "甲區人多密度高、乙區人少密度低", "甲區人少密度低、乙區人多密度高"], "a": 2, "e": "甲是東部農業區，人多、密度高；乙是西部畜牧區，人少、密度低。", "rep": false, "img": "g3-q45", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-46", "no": 46, "c": "e9", "src": "114上翰林社會2上B卷 卷4 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(四)是中國人口增加示意圖，若僅依據圖中資訊判斷，甲階段相較於乙階段，可能具有下列哪一項特徵？", "o": ["勞動力較充足", "市場規模較小", "人口密度較低", "人口壓力較小"], "a": 0, "e": "甲階段（2011 年後）人口數比乙階段（1804 年）多很多，勞動人口較充足；但人口多也代表市場大、密度高、壓力大。", "rep": false, "img": "g3-q46", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-47", "no": 47, "c": "e7", "src": "114上翰林社會2上B卷 卷4 第 16 題", "st": "考卷", "ctx": "", "fig": "圖(五)為大批單身男子參加光棍節聯誼的漫畫圖", "q": "圖(五)所呈現的是中國某個人口問題，根據圖中內容判斷，該現象在 2020 年後將更趨嚴重。此問題的產生與下列何者的關係最密切？「2020年光棍節，求介紹女朋友」", "o": ["生育政策及重男輕女觀念", "人口過多及教育經費不足", "經濟改革開放及區域不均", "工業過度發展及全球暖化"], "a": 0, "e": "光棍問題來自一胎化政策加上重男輕女觀念，導致男多於女。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-48", "no": 48, "c": "e7", "src": "114上翰林社會2上B卷 卷4 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列哪一張圖（♂：男，♀：女）最能呈現出中國目前新生兒的性別比情形？", "o": ["男女各半", "女多於男", "全部是男", "男多於女（男約六成）"], "a": 3, "e": "中國新生兒性別比約 109，男嬰略多於女嬰，圓餅圖中「男」占比較大的 (D) 最接近。", "rep": false, "img": "g3-q48", "imgnote": "", "fh": "", "maps": ["g3-map-sex"], "chk": ""}, {"id": "g3-49", "no": 49, "c": "e6", "src": "114上翰林社會2上B卷 卷4 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(六)是中國國家統計局於 2024 年發布的近 20 年中國自然增加率的資料。依據圖中資訊判斷，下列關於該期間人口現象的敘述何者正確？", "o": ["人口持續增加", "人口先增後減", "人口密度不變", "人口持續減少"], "a": 1, "e": "自然增加率先為正（人口增加），2022 年後轉為負值（人口減少），所以人口先增後減。", "rep": false, "img": "g3-q49", "imgnote": "", "fh": "", "maps": ["g3-map-popstat"], "chk": ""}, {"id": "g3-50", "no": 50, "c": "e2", "src": "114上翰林社會2上B卷 卷4 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國自 2022 年起，牛奶價格跌破平均生產成本，對酪農業造成嚴重衝擊。依據中國的經濟發展情形判斷，文中提及的產品之主要產區最可能包括圖(七)中哪一行政區？", "o": ["甲", "乙", "丙", "丁"], "a": 0, "e": "甲是內蒙古，以畜牧業為主，是牛奶的主要產區。", "rep": false, "img": "g3-q50", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-51", "no": 51, "c": "e8", "src": "114上翰林社會2上B卷 卷4 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國於 2015 年結束「一胎化政策」，開放「生育二胎」，2021 年更通過「三孩政策」。由以上的政策轉變可以判斷，中國想要解決的問題最可能不包括下列何者？", "o": ["人口高齡化", "性別比失衡", "勞動力人口降低", "經濟發展趨緩"], "a": 3, "e": "原卷解析：鼓勵生育可以改善人口高齡化、勞動人口降低，也能讓性別比失衡的問題有機會改善；「經濟發展趨緩」不是人口政策直接要解決的人口問題，所以答案是 (D)。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "原卷答案 (D)，觀念有討論空間"}, {"id": "g3-52", "no": 52, "c": "e4", "src": "114上翰林社會2上B卷 卷4 第 21 題", "st": "考卷", "ctx": "", "fig": "圖(八)：甲圖標示「環境負載力高」，草原上牛羊成群；乙圖標示「環境負載力低」，乾旱草地上只有兩三隻羊。", "q": "圖(八)是老師在解釋環境負載力概念時所呈現的示意圖，下列有關圖中甲、乙兩情境的說明何者正確？", "o": ["甲供養的生物數量較乙少", "甲的環境負載力較乙高", "甲的生活環境遠較乙惡劣", "甲分解廢棄物的能力較乙低"], "a": 1, "e": "甲圖水草豐美、牛羊多，表示環境負載力較高。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-53", "no": 53, "c": "e6", "src": "114上翰林社會2上B卷 卷4 第 22 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(九)中甲、乙兩線是中國人口出生率和死亡率的變化，關於圖中綠段的意義，下列何者最正確？", "o": ["甲為死亡率", "乙為出生率", "甲＋乙＝自然增加率", "甲－乙＝自然增加率"], "a": 3, "e": "甲是出生率、乙是死亡率，出生率－死亡率＝自然增加率。", "rep": false, "img": "g3-q53", "imgnote": "", "fh": "", "maps": ["g3-map-popstat"], "chk": ""}, {"id": "g3-54", "no": 54, "c": "e1", "src": "114上翰林社會2上B卷 卷4 第 23 題", "st": "考卷", "ctx": "", "fig": "", "q": "阿光走訪中國的新疆及西藏地區，發現多數居民傳統上以驅趕牲畜找尋水源及牧草的方式維生，因此少數可以發展農業活動的地區就成為人口集中的精華區。上述精華區的共同特色為何？", "o": ["水源供應充沛", "宗教信仰虔誠", "屬於平原地形", "與海洋距離近"], "a": 0, "e": "西部乾燥，能發展農業的地方一定是有水源的綠洲或河谷。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-55", "no": 55, "c": "e5", "src": "114上翰林社會2上B卷 卷4 第 24 題", "st": "考卷", "ctx": "", "fig": "圖(十)為東南亞唐人街漢字招牌街景照片", "q": "圖(十)是小文在網站上閱讀到的標題及照片，依據圖中資訊判斷，該網頁所提及的國家最可能位於下列哪一地區？「東南亞許多都市街頭上一半以上的招牌寫著漢字，很多當地人都能講中文」", "o": ["中亞", "東北亞", "南亞", "東南亞"], "a": 3, "e": "東南亞有許多華人，街頭常見漢字招牌，很多人會說中文。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-56", "no": 56, "c": "e8", "src": "114上翰林社會2上B卷 卷4 題組 (一) 1", "st": "考卷", "ctx": "", "fig": "", "q": "圖(十一)是中國在 1980、2020 年及預測 2040 年的人口金字塔圖，從圖中人口變化的趨勢，可以預估中國將面臨的社會、經濟等發展的問題。若中國的人口結構持續朝此趨勢發展，則未來可能發生的人口問題不包括下列何者？", "o": ["少子化現象", "人口高齡化", "勞動力不足", "外移人口多"], "a": 3, "e": "從金字塔可看出少子化、高齡化、勞動力不足，但看不出「外移人口多」。", "rep": false, "img": "g3-q56", "imgnote": "", "fh": "", "maps": ["g3-map-pyramid"], "chk": ""}, {"id": "g3-57", "no": 57, "c": "e9", "src": "114上翰林社會2上B卷 卷4 題組 (一) 2", "st": "考卷", "ctx": "圖(十一)是中國在 1980、2020 年及預測 2040 年的人口金字塔圖，從圖中人口變化的趨勢，可以預估中國將面臨的社會、經濟等發展的問題。", "fig": "", "q": "承上題，從圖中不同時期的人口變化判斷，中國的扶養比變化情形應為下列何者？", "o": ["持續上升", "持續下降", "先升後降", "先降後升"], "a": 3, "e": "1980→2020 壯年人口比例上升（扶養比下降），2020→2040 壯年比例下降（扶養比上升），所以先降後升。", "rep": true, "img": "g3-q56", "imgnote": "", "fh": "", "maps": ["g3-map-pyramid"], "chk": ""}, {"id": "g3-58", "no": 58, "c": "e6", "src": "114上翰林社會2上B卷 卷4 題組 (一) 3", "st": "考卷", "ctx": "圖(十一)是中國在 1980、2020 年及預測 2040 年的人口金字塔圖，從圖中人口變化的趨勢，可以預估中國將面臨的社會、經濟等發展的問題。", "fig": "", "q": "承上題，由圖中甲到乙的幼年人口比例銳減，其原因最可能為下列何者？", "o": ["三孩政策", "一胎化政策", "鼓勵生育政策", "生育二胎政策"], "a": 1, "e": "甲（1980）到乙（2020）幼年人口銳減，主因是 1979 年起的一胎化政策。", "rep": false, "img": "g3-q56", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-59", "no": 59, "c": "e5", "src": "114上翰林社會2上B卷 卷4 題組 (二) 4", "st": "考卷", "ctx": "", "fig": "", "q": "《東南亞的華人飲食與全球化》一書中提及東南亞有許多華人是在明清時期由中國某些地區移居至當地，這些華人將故鄉的生活習慣及風俗帶入東南亞，並且介紹了許多華人的美食及製作原料與製作方式。文中的概念適合用哪一個詞彙描述？", "o": ["游牧", "文化擴散", "山牧季移", "環境負載力"], "a": 1, "e": "華人把家鄉的生活習慣與美食帶到東南亞，就是文化擴散。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-60", "no": 60, "c": "e5", "src": "114上翰林社會2上B卷 卷4 題組 (二) 5", "st": "考卷", "ctx": "《東南亞的華人飲食與全球化》一書中提及東南亞有許多華人是在明清時期由中國某些地區移居至當地，這些華人將故鄉的生活習慣及風俗帶入東南亞，並且介紹了許多華人的美食及製作原料與製作方式。", "fig": "", "q": "承上題，文中提及明清時期由中國某些地區的華人移居至東南亞，該地區為圖(十二)中何者？", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "明清時期移民來自東南沿海的福建、廣東，圖中的丙。", "rep": true, "img": "g3-q60", "imgnote": "", "fh": "", "maps": ["g3-map-sea"], "chk": ""}, {"id": "g3-61", "no": 61, "c": "e5", "src": "114上翰林社會2上B卷 卷4 題組 (二) 6", "st": "考卷", "ctx": "《東南亞的華人飲食與全球化》一書中提及東南亞有許多華人是在明清時期由中國某些地區移居至當地，這些華人將故鄉的生活習慣及風俗帶入東南亞，並且介紹了許多華人的美食及製作原料與製作方式。", "fig": "", "q": "承上題，該地區的華人移居東南亞，最可能與其原居地所具有的何種地理環境有關？", "o": ["氣候較乾燥", "終年均低溫", "地震較頻繁", "山多平原少"], "a": 3, "e": "閩粵一帶山多平原少、耕地不足，人口增加後只好向海外謀生。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-sea"], "chk": ""}, {"id": "g3-62", "no": 62, "c": "e1", "src": "114上翰林社會2上B卷 卷4 題組 (二) 7", "st": "考卷", "ctx": "《東南亞的華人飲食與全球化》一書中提及東南亞有許多華人是在明清時期由中國某些地區移居至當地，這些華人將故鄉的生活習慣及風俗帶入東南亞，並且介紹了許多華人的美食及製作原料與製作方式。", "fig": "", "q": "承上題，東南亞國家常見的炒粿條是由明清時期的移民所帶來，此一食物是以哪一作物為原料製作而成？", "o": ["高粱", "小麥", "水稻", "玉米"], "a": 2, "e": "粿條是用米做的，原料是水稻，來自南方水田區。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-63", "no": 63, "c": "e8", "src": "114上翰林社會2上C卷 卷4 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "2023 年中國老年人口約占總人口 16%，顯見老年人口持續增加而幼年人口減少。下列何者是為了解決上述人口議題提出的政策？", "o": ["均衡區域發展", "鼓勵國際遷移", "通過三孩政策", "偏鄉交通建設"], "a": 2, "e": "三孩政策是為了鼓勵生育，減緩高齡化。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-64", "no": 64, "c": "e7", "src": "114上翰林社會2上C卷 卷4 第 2 題", "st": "考卷", "ctx": "", "fig": "表(一)：新生兒性別比——美滿鎮 80、幸福村 90、福氣鎮 100、延年村 110", "q": "傳統習俗上，家中生男嬰時，要準備油飯分送親友。表(一)中四個村鎮，在 2024 年同時有 1,500 戶人家增添一名新生兒，以「性別比」推測，哪一村鎮訂製油飯的人家最少？", "o": ["美滿鎮", "幸福村", "福氣鎮", "延年村"], "a": 0, "e": "油飯是生男嬰才送，性別比最低（80）的美滿鎮男嬰最少，訂油飯的最少。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-sex"], "chk": ""}, {"id": "g3-65", "no": 65, "c": "e3", "src": "114上翰林社會2上C卷 卷4 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "孟修根據中國人口分布圖，以黑河、騰衝的界線，分為人口稠密區與稀疏區，下列哪幅圖最可能是孟修繪製的圖片？", "o": ["由西向東略偏北的斜線", "由東北斜向西南的斜線", "接近南北向的直線", "由西北斜向東南的斜線"], "a": 1, "e": "黑河在東北、騰衝在西南，連線是一條從東北斜到西南的線，選 (B)。", "rep": false, "img": "g3-q65", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-66", "no": 66, "c": "e3", "src": "114上翰林社會2上C卷 卷4 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "阿雄在地理課堂報告中國人口分布不平均的特色，他可以用下列哪個現象來說明？", "o": ["人口數世界第二", "浮現高齡化問題", "大都市集中東部", "周圍有許多鄰國"], "a": 2, "e": "大都市集中在東部，正是人口東密西疏、分布不均的表現。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-67", "no": 67, "c": "e4", "src": "114上翰林社會2上C卷 卷4 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "自然環境條件會影響環境負載力的高低，下列哪個地區的自然條件較差，因此環境負載力較低？", "o": ["青藏高原", "黃土高原", "華北平原", "東南丘陵"], "a": 0, "e": "青藏高原地勢高、氣候寒冷，自然條件差，環境負載力低。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-68", "no": 68, "c": "e9", "src": "114上翰林社會2上C卷 卷4 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國政府於 2015 年實施一對夫婦可生育兩個孩子的政策，目的是改善當前人口成長對未來國家發展的隱憂，預估每年將新增 800 萬出生人口。上述政策是為了解決何種問題？", "o": ["人口分布不均", "城鄉發展不一", "扶養比下降", "勞動力減少"], "a": 3, "e": "開放二胎是擔心少子化造成勞動力減少。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-69", "no": 69, "c": "e6", "src": "114上翰林社會2上C卷 卷4 第 7 題", "st": "考卷", "ctx": "", "fig": "圖(一)：中國生育率長條圖——1950～1955 年約 6、1975～1980 年約 3.5、1995～2000 年約 1.8", "q": "圖(一)為中國歷年來的生育率變化，圖中生育率的變化趨勢，是受到下列哪一項政策的影響？", "o": ["實施一胎化政策", "推廣男女一樣好", "實施經濟改革開放", "限制戶籍遷移"], "a": 0, "e": "1975 年後生育率大幅下降，是因為推行一胎化（計畫生育）政策。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-70", "no": 70, "c": "e6", "src": "114上翰林社會2上C卷 卷4 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國在 1979 年提出一胎化政策，目的是為了因應當時中國人口組成所帶來的社會問題。當時中國人口金字塔圖最接近下列哪一種類型？", "o": ["增加型（底寬頂窄金字塔）", "縮減型（底窄中寬彈頭型）", "穩定型（各年齡層寬度接近）", "倒金字塔型（頂寬底窄）"], "a": 0, "e": "一胎化之前出生率很高，人口金字塔是底寬頂窄的增加型（A）。", "rep": false, "img": "g3-q70", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-71", "no": 71, "c": "e6", "src": "114上翰林社會2上C卷 卷4 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(二)為中國人口統計圖，根據圖中資料判斷，下列敘述何者正確？", "o": ["目前人口數超過 16 億人口", "自然增加率長期呈下降趨勢", "社會增加率長期高於正成長", "2015 年出生率低於死亡率"], "a": 1, "e": "圖中自然增加率長期呈下降趨勢；人口未超過 16 億，2015 年自然增加率仍為正。", "rep": false, "img": "g3-q71", "imgnote": "", "fh": "", "maps": ["g3-map-popstat"], "chk": ""}, {"id": "g3-72", "no": 72, "c": "e7", "src": "114上翰林社會2上C卷 卷4 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國近年來密集宣導「培育女孩成才，建設幸福家庭」、「今天的女孩，明天的建設者」等口號，是為了解決中國哪一種人口問題？", "o": ["人口數太多", "性別比偏高", "扶養負擔重", "流動人口多"], "a": 1, "e": "宣導重視女孩，是為了改善性別比偏高（男多女少）的問題。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-73", "no": 73, "c": "e1", "src": "114上翰林社會2上C卷 卷4 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國人口多聚集在農業發達的東部地區，下列有關東部地區有利於農業發展的敘述，何者正確？", "o": ["均屬溫帶季風氣候", "一年四季降水平均", "平原地形分布廣闊", "河流水量終年豐穩"], "a": 2, "e": "東部平原廣闊，有利農業；東部並非全是溫帶季風氣候，降水也集中在夏季。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-74", "no": 74, "c": "e5", "src": "114上翰林社會2上C卷 卷4 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "印尼最大的唐人街位於雅加達的草埔，當地知名的建築物金德院，便是當地最早的華人寺廟之一。除印尼之外，東南亞其他國家也有不少華人居住。這些華人的祖先原先最可能居住在中國哪種地理環境？", "o": ["丘陵或沿海平原", "水草豐美的草原", "群山環繞的盆地", "地處內陸的沙漠"], "a": 0, "e": "東南亞華人多來自福建、廣東，原居地是丘陵和沿海平原。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-sea"], "chk": ""}, {"id": "g3-75", "no": 75, "c": "e8", "src": "114上翰林社會2上C卷 卷4 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "隨著醫療衛生進步與生活條件改善，日本等先進國家陸續進入超高齡社會，發展較晚的中國也已進入高齡社會。除了上述的原因之外，中國快速進入高齡社會與下列何者較相關？", "o": ["國土面積廣大", "大量移民移入", "實施人口政策", "重視老人福利"], "a": 2, "e": "中國快速進入高齡社會，主要是實施一胎化，幼年人口快速減少。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-76", "no": 76, "c": "e5", "src": "114上翰林社會2上C卷 卷4 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "臺灣是一個移民社會，所以可以品嘗到多元的飲食文化，例如：中國北方的麵食和南方的米食。有關上述現象呈現多元美食文化的主要因素為何？", "o": ["來自中國的文化擴散", "曾經淪為多國殖民地", "重視國際貿易的發展", "臺灣原住民傳統文化"], "a": 0, "e": "臺灣居民多來自中國，帶來北方麵食和南方米食，是文化擴散。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-77", "no": 77, "c": "e1", "src": "114上翰林社會2上C卷 卷4 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "大雄在地理課堂報告中國分區特色，圖(三)為主要分區地圖。依據圖中內容判斷，大雄報告的主題應為下列何者？", "o": ["中國主要農業與牧業區", "中國的水田、旱田分區", "中國放牧與游牧區分界", "中國溫帶與熱帶的分界"], "a": 0, "e": "圖中分界線大致是年雨量 500mm 線，分出東部農業區與西部牧業區。", "rep": false, "img": "g3-q77", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-78", "no": 78, "c": "e5", "src": "114上翰林社會2上C卷 卷4 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(四)為早期華人向外遷移的示意圖，圖中華人移民的範圍呈現下列何種趨勢？", "o": ["多半移居至西半球", "多半移居至南半球", "主要外移至東南亞", "外移周邊先進國家"], "a": 2, "e": "箭頭多從中國東南沿海指向東南亞各地。", "rep": false, "img": "g3-q78", "imgnote": "", "fh": "", "maps": ["g3-map-sea"], "chk": ""}, {"id": "g3-79", "no": 79, "c": "e7", "src": "114上翰林社會2上C卷 卷4 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(五)為世界及部分國家新生兒性別比圖，根據圖中內容判斷，下列說明何者正確？", "o": ["中國出生人數高於臺灣與美國", "圖中各國均呈現重男輕女現象", "中國新生兒性別比嚴重失衡", "美國新生兒性別比女多於男"], "a": 2, "e": "中國新生兒性別比 109，比世界平均 105 高很多，失衡嚴重。", "rep": false, "img": "g3-q79", "imgnote": "", "fh": "", "maps": ["g3-map-sex"], "chk": ""}, {"id": "g3-80", "no": 80, "c": "e7", "src": "114上金安翰版社會2上A卷 第4次練習 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "「中國衛生部門規定婦產科醫生只能告知產婦及其家屬胎兒健康與否，不得透露其他訊息，違者將取消醫生執業的執照……。」上述是為解決中國哪項問題？", "o": ["人口數量龐大", "人口結構失衡", "人口素質較低", "流動人口眾多"], "a": 1, "e": "禁止透露胎兒性別，是為了避免選擇性別生育，改善男多女少的人口結構失衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-81", "no": 81, "c": "e5", "src": "114上金安翰版社會2上A卷 第4次練習 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "右圖為中國東南沿海早期人口遷移的示意圖。移民者將原鄉文化帶到移居地，呈現何種文化現象？", "o": ["文化融合", "文化傳承", "文化創新", "文化擴散"], "a": 3, "e": "移民把原鄉文化帶到移居地，稱為文化擴散。", "rep": false, "img": "g3-q81", "imgnote": "", "fh": "", "maps": ["g3-map-sea"], "chk": ""}, {"id": "g3-82", "no": 82, "c": "e3", "src": "114上金安翰版社會2上A卷 第4次練習 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國人口數量龐大但分布不均，主要受到自然環境影響，下列哪一種自然條件地區的人口較稠密？", "o": ["季風氣候區、平原", "季風氣候區、丘陵", "乾燥氣候區、盆地", "乾燥氣候區、高原"], "a": 0, "e": "季風氣候區降水多、平原地勢平坦，最適合農業，人口最稠密。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-83", "no": 83, "c": "e1", "src": "114上金安翰版社會2上A卷 第4次練習 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "傳統上，中國北部地區和南部地區有農業上「南稻北麥」的差異，區隔中國南方、北方的天然地理分界是下列哪座山脈？", "o": ["秦嶺", "南嶺", "天山", "大興安嶺"], "a": 0, "e": "南稻北麥以秦嶺、淮河為界，山脈是秦嶺。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-84", "no": 84, "c": "e3", "src": "114上金安翰版社會2上A卷 第4次練習 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國的人口分布不均，右圖中的哪一條線是人口稠密區和稀疏區的分界？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "人口疏密分界是黑河—騰衝線，圖中由東北斜到西南的丁線。", "rep": false, "img": "g3-q84", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-85", "no": 85, "c": "e5", "src": "114上金安翰版社會2上A卷 第4次練習 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國東南沿海地區於明清時期，部分居民向海外謀生，其主要原因為何？", "o": ["水、旱災頻繁", "交通運輸不便", "人口急遽增加", "政治動盪紛擾"], "a": 2, "e": "明清時期東南沿海人口急遽增加、耕地不足，部分居民只好到海外謀生。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-86", "no": 86, "c": "e5", "src": "114上金安翰版社會2上A卷 第4次練習 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "金馬獎是臺灣電影業界具代表性的獎項，有「華語電影奧斯卡金像獎」的美譽，只要作品逾半使用華語，或導演與團隊創作人員有 7 名為華人，符合條件皆能報名，不受國籍限制。依此判斷，金馬獎除了臺灣、中國及香港等地外，最可能出現下列哪一地區的影片參展？", "o": ["歐洲", "北美洲", "東北亞", "東南亞"], "a": 3, "e": "東南亞有許多華人，最可能有華語電影參展。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-87", "no": 87, "c": "e2", "src": "114上金安翰版社會2上A卷 第4次練習 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "「全世界走最多路的是蒙古人！全世界搬家最勤的是蒙古人！蒙古人的歷史就是在轉場中播寫！」以上是描述蒙古人的一首詩，依此判斷，蒙古人的傳統生活方式為何？", "o": ["放牧", "游牧", "圈牧", "游耕"], "a": 1, "e": "「走最多路、搬家最勤」，是逐水草而居的游牧。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-88", "no": 88, "c": "e4", "src": "114上金安翰版社會2上A卷 第4次練習 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "「環境負載力」是指生活環境能供養生物數量及分解穢物的能力。右圖為幸福國四個地區的人口分布資料，圖中每點代表 5000 人。依此判斷，哪個地區的環境負載力最高？", "o": ["甲", "乙", "丙", "丁"], "a": 0, "e": "四區人數相同，甲的比例尺 1:25000 最大，代表實際面積最小、密度最高，能養活最多人，環境負載力最高。", "rep": false, "img": "g3-q88", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-89", "no": 89, "c": "e8", "src": "114上金安翰版社會2上A卷 第4次練習 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "右圖為中國 2000 年及推估 2050 年扶養比的變化情形。根據內容判斷，中國將面臨哪項人口問題？", "o": ["出生率太高", "性別比失衡", "人口高齡化", "人口素質低"], "a": 2, "e": "2050 年需要扶養的老人變多，表示人口高齡化。", "rep": false, "img": "g3-q89", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-90", "no": 90, "c": "e3", "src": "114上金安翰版社會2上A卷 第4次練習 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "2019 年底，中國爆發「新冠病毒」疫情。2020 年 1 月，恰逢民眾返鄉過年，導致疫情迅速擴散各省。據統計各省市確診病例中，西藏自治區確診病例人數最少，其主要原因為何？", "o": ["人口密度較低", "失業人口眾多", "都市人口外移", "老年人口較少"], "a": 0, "e": "西藏人口稀少、密度低，病毒不容易傳播。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-91", "no": 91, "c": "e3", "src": "114上金安翰版社會2上A卷 第4次練習 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列為中國地勢分布簡圖，圖中哪一個地區的人口最多，密度最高？", "o": ["甲", "乙", "丙", "丁一樣多"], "a": 2, "e": "丙位於地勢第三階梯，多平原丘陵，人口最多、密度最高。", "rep": false, "img": "g3-q91", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-92", "no": 92, "c": "e6", "src": "114上金安翰版社會2上A卷 第4次練習 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "「李家為老上海的大家族，人口眾多，形成三代同堂的大家族特色。輩分最小的小顏發現他的祖父有六個兄弟，父親有三個兄弟，而小顏卻僅有他一個人，沒有兄弟姊妹。」根據上文推論，中國人口出現下列何種現象？", "o": ["出生率降低", "死亡率降低", "人口移入減少", "人口移出增加"], "a": 0, "e": "三代下來兄弟越來越少，表示出生率降低（一胎化）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-93", "no": 93, "c": "e1", "src": "114上金安翰版社會2上A卷 第4次練習 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "昔日中國的經濟以農業為主，王老師要同學們利用中國三大氣候區分布圖為底，繪製出中國適合農業發展興盛的區域，最後繪製出的區域最有可能是根據下列何者來考量？", "o": ["最冷月均溫 > 0℃", "最冷月均溫 > 18℃", "年降水量 > 500mm", "年降水量 > 1000mm"], "a": 2, "e": "農業區與畜牧區的分界大致是年降水量 500mm 線，> 500mm 適合農業。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-94", "no": 94, "c": "e2", "src": "114上金安翰版社會2上A卷 第4次練習 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "內蒙古自治區的西部以「游牧」為主，新疆維吾爾自治區的天山地區則以「山牧季移」為主。這兩個地區畜牧方式有所不同，其主要受到下列哪項因素的影響？", "o": ["地形起伏", "溫差大小", "季風風向", "緯度高低"], "a": 0, "e": "內蒙古西部是高原上的游牧，天山是依海拔高低的山牧季移，主因是地形起伏。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-95", "no": 95, "c": "e1", "src": "114上金安翰版社會2上A卷 第4次練習 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國人口分布不均，主要是受到地形、氣候等自然環境差異的影響。綠洲為人口稠密地區之一，主要分布於下列何種氣候？", "o": ["氣候圖 (A)", "氣候圖 (B)", "氣候圖 (C)", "氣候圖 (D)"], "a": 1, "e": "綠洲出現在乾燥氣候區，要選年雨量很少的乾燥氣候圖 (B)。", "rep": true, "img": "g3-q95", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-96", "no": 96, "c": "e8", "src": "114上金安翰版社會2上A卷 第4次練習 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "右圖為中國人口結構趨勢的推估圖。根據圖中資訊判斷，中國在哪一年後將邁入超高齡社會？", "o": ["2020 年", "2030 年", "2040 年", "2060 年"], "a": 2, "e": "65 歲以上人口超過 20% 為超高齡社會，圖中約在 2040 年後超過 20%。", "rep": false, "img": "g3-q96", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-97", "no": 97, "c": "e8", "src": "114上金安翰版社會2上A卷 第4次練習 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "「421」家庭時代是因中國計畫生育政策而產生的現象，即家庭由 4 名祖父母、2 名父母和 1 名子女組成。依此判斷，中國未來將面臨下列何種社會現象？", "o": ["失業率上升", "性別比失衡", "勞動力增加", "扶養比提高"], "a": 3, "e": "421 家庭表示一個孩子未來要扶養父母和祖父母，扶養比提高。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-98", "no": 98, "c": "e7", "src": "114上金安翰版社會2上A卷 第4次練習 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "「人口販運集團以非法方式從中國周邊國家（越南、緬甸等）誘拐少女，賣到中國當新娘。」上述凸顯出中國的何種人口問題？", "o": ["人口分布不均", "勞動力不足", "邁入高齡社會", "性別比嚴重失衡"], "a": 3, "e": "從周邊國家買新娘，表示中國男多女少，性別比嚴重失衡。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-99", "no": 99, "c": "e4", "src": "114上金安翰版社會2上A卷 第4次練習 第 20 題", "st": "考卷", "ctx": "", "fig": "表：界線以東——土地面積 43%、人口 94%；界線以西——土地面積 57%、人口 6%", "q": "右表是中國以黑河至騰衝為界分成東西半部。依表判斷，造成這種人口分布差異現象，可用下列何者解釋？", "o": ["全球的暖化", "土地肥沃度", "環境負載力", "政府的政策"], "a": 2, "e": "東部環境負載力高，能養活較多人；西部環境負載力低，人口稀少。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-100", "no": 100, "c": "e2", "src": "114上金安翰版社會2上A卷 第4次練習 第 21 題", "st": "考卷", "ctx": "", "fig": "", "q": "右圖為中國五大地形面積比例圖，圖中的哪兩種地形區的牧民會順應季節變化，春天上山放牧，秋天下山避冬的畜牧方式？", "o": ["甲乙", "甲戊", "乙丙", "丙丁"], "a": 3, "e": "山牧季移出現在高原和山地，圖中丙（高原 26%）、丁（山地 33%）。", "rep": false, "img": "g3-q100", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-101", "no": 101, "c": "e3", "src": "114上金安翰版社會2上A卷 第4次練習 第 22 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國春運是指在春節期間發生的大規模、高交通運輸壓力的現象，被認為是人類史上規模最大的週期性遷徙活動。由中國人口分布不均的特徵判斷，春節期間的流動規模，呈現下列何種現象？", "o": ["東南熱、西北冷", "東北熱、西南冷", "西北熱、東南冷", "西南熱、東北冷"], "a": 0, "e": "東南沿海人口多、外出工作的人多，春運流動量大；西北人口少，所以東南熱、西北冷。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-102", "no": 102, "c": "e3", "src": "114上金安翰版社會2上A卷 第4次練習 第 23 題", "st": "考卷", "ctx": "", "fig": "表：甲 面積（東大、西小）；乙 人口總數（東多、西少）；丙 人口密度（東低、西高）；丁 地形（東：平原、丘陵；西：高原、山地）", "q": "從黑河到騰衝之間的連線，是中國人口疏密的重要分界線。下表是有關此連線的東、西部特色比較，哪些項目正確？", "o": ["甲乙", "丙丁", "甲丙", "乙丁"], "a": 3, "e": "東部面積較小（甲錯）、人口多（乙對）、密度高（丙錯）、地形多平原丘陵（丁對）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-103", "no": 103, "c": "e5", "src": "114上金安翰版社會2上A卷 第4次練習 第 24 題", "st": "考卷", "ctx": "", "fig": "", "q": "隨著移民的腳步，華人文化也因此向外擴散，下列何者不是華人文化向外擴散的例證？", "o": ["泰國曼谷的唐人街中文招牌林立", "各國風景區皆可看到中國人身影", "新加坡居民講華語，並信仰媽祖", "俄羅斯掀起一股學習華語的熱潮"], "a": 1, "e": "到各國觀光是旅遊，不是把文化帶到當地，不算文化擴散。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-104", "no": 104, "c": "e8", "src": "114上金安翰版社會2上A卷 第4次練習 第 25 題", "st": "考卷", "ctx": "", "fig": "表：0～14 歲——1990 年 27.69%、2000 年 22.89%、2010 年 16.60%、2020 年 17.95%；65 歲以上——5.57%、6.96%、8.87%、13.50%", "q": "下表為中國不同年份的人口普查部分資料。觀察表中幼年人口比例的變動，下列何者最可能是造成 2010 到 2020 年微幅變化的原因之一？", "o": ["醫療衛生進步", "環境品質改善", "開放生育二胎", "國民所得提高"], "a": 2, "e": "2010 到 2020 年幼年人口比例微幅回升，是因為 2015 年開放生育二胎。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-105", "no": 105, "c": "e8", "src": "114上金安翰版社會2上A卷 第4次練習 題組 (一) 26", "st": "考卷", "ctx": "", "fig": "", "q": "中國為降低人口成長壓力，於 1979 年通過實施「一胎化政策」。2010 年，第六次人口普查顯示，中國生育率下降到 1.18，即每一位育齡婦女平均生 1.18 個小孩。生育率低於 1.5 就稱為「超低生育率」，每位婦女須生育 2.1 個子女才能維持人口平穩，這個數字被稱為「更替生育率」。中國實施 30 多年的「一胎化政策」，造成人口結構呈現何種現象？", "o": ["多子化與高齡化", "少子化與高齡化", "多子化與幼齡化", "少子化與幼齡化"], "a": 1, "e": "一胎化使孩子變少（少子化），老年人比例相對提高（高齡化）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-106", "no": 106, "c": "e8", "src": "114上金安翰版社會2上A卷 第4次練習 題組 (一) 27", "st": "考卷", "ctx": "中國為降低人口成長壓力，於 1979 年通過實施「一胎化政策」。2010 年，第六次人口普查顯示，中國生育率下降到 1.18，即每一位育齡婦女平均生 1.18 個小孩。生育率低於 1.5 就稱為「超低生育率」，每位婦女須生育 2.1 個子女才能維持人口平穩，這個數字被稱為「更替生育率」。", "fig": "", "q": "右圖為中國生育率統計，根據上文的資料判斷，中國在哪個年代以後，呈現「超低生育率」的現象？", "o": ["1970 年", "1980 年", "1990 年", "2000 年"], "a": 3, "e": "生育率 1.5 以下為超低生育率，圖中 2000 年降到約 1.2，所以 2000 年以後。", "rep": false, "img": "g3-q106", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-107", "no": 107, "c": "e6", "src": "114上金安翰版社會2上A卷 第4次練習 題組 (二) 28", "st": "考卷", "ctx": "", "fig": "", "q": "2022 年底，中國已有 14.1 億人口，比 2021 年底少 85 萬人，這是 61 年以來首次下降，而 1961 年是中國大饑荒的最後一年。2022 年，中國約有 956 萬名嬰兒出生，比一年前的 1062 萬銳減 106 萬，創 1950 年以來最低水準。儘管中國政府努力鼓勵生育，但是生育率未見大幅提升。下列何者最可能是中國 1978 年以前的人口金字塔圖？", "o": ["圖 (A)", "圖 (B)", "圖 (C)", "圖 (D)"], "a": 0, "e": "1978 年以前尚未實施一胎化，出生率高，金字塔為底寬頂窄的增加型 (A)。", "rep": false, "img": "g3-q107", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-108", "no": 108, "c": "e6", "src": "114上金安翰版社會2上A卷 第4次練習 題組 (二) 29", "st": "考卷", "ctx": "2022 年底，中國已有 14.1 億人口，比 2021 年底少 85 萬人，這是 61 年以來首次下降，而 1961 年是中國大饑荒的最後一年。2022 年，中國約有 956 萬名嬰兒出生，比一年前的 1062 萬銳減 106 萬，創 1950 年以來最低水準。儘管中國政府努力鼓勵生育，但是生育率未見大幅提升。", "fig": "", "q": "2022 年，中國約有 956 萬名嬰兒出生，出生率不高，但出生數仍多。這項象與下列何者最相關？", "o": ["出生率越來越高", "死亡率越來越低", "國際移民增多", "人口基數極大"], "a": 3, "e": "出生率不高但出生人數仍多，是因為人口基數極大。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-109", "no": 109, "c": "e8", "src": "114上金安翰版社會2上A卷 第4次練習 題組 (二) 30", "st": "考卷", "ctx": "2022 年底，中國已有 14.1 億人口，比 2021 年底少 85 萬人，這是 61 年以來首次下降，而 1961 年是中國大饑荒的最後一年。2022 年，中國約有 956 萬名嬰兒出生，比一年前的 1062 萬銳減 106 萬，創 1950 年以來最低水準。儘管中國政府努力鼓勵生育，但是生育率未見大幅提升。", "fig": "", "q": "為解決人口下滑危機，下列何者為中國最新的人口政策？", "o": ["一胎化", "生育二胎", "三孩政策", "男孩女孩一樣好"], "a": 2, "e": "中國 2021 年通過三孩政策，是最新的人口政策。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-110", "no": 110, "c": "e1", "src": "講義第 33 頁 學習即時通 3-1 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "第一級產業活動受到氣候等自然環境的影響甚大，右圖為中國農牧業分布圖，其分界線大致與下列哪兩個氣候分界線相符？", "o": ["草原氣候、沙漠氣候", "沙漠氣候、高地氣候", "季風氣候、草原氣候", "草原氣候、高地氣候"], "a": 2, "e": "農牧分界線（500mm 等雨量線）大致是季風氣候與草原（乾燥）氣候的分界。", "rep": false, "img": "g3-q110", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-111", "no": 111, "c": "e1", "src": "講義第 33 頁 學習即時通 3-1 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "中國東半部因氣候較溼潤，加上地形較平坦，因此成為中國主要的作物栽培區，但依據氣候環境的不同，呈現南方水稻、北方小麥的分布情形是以下列何者為分界？", "o": ["南嶺、珠江", "巫山、長江", "天山、黃河", "秦嶺、淮河"], "a": 3, "e": "南稻北麥以秦嶺、淮河為界。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-112", "no": 112, "c": "e2", "src": "講義第 33 頁 學習即時通 3-1 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "中國各地自然環境不同，所採用的畜牧方式也不盡相同，右圖中甲地區採用的哪一種畜牧方式？", "o": ["欄牧", "放牧", "游牧", "山牧季移"], "a": 3, "e": "甲位於青藏高原，採山牧季移。", "rep": false, "img": "g3-q112", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-113", "no": 113, "c": "e3", "src": "講義第 34 頁 學習即時通 3-2 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "因受到地理環境影響，中國呈現人口分布不均的狀況。下列哪一張圖最能夠表達出其現況？", "o": ["北「密」、南「疏」", "西北「疏」、東南「密」", "西「密」、東「疏」", "西南「密」、東北「疏」"], "a": 1, "e": "中國人口東南密、西北疏，分界線從東北斜向西南，選 (B)。", "rep": true, "img": "g3-q113", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-114", "no": 114, "c": "e3", "src": "講義第 34 頁 學習即時通 3-2 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "受到自然環境及產業活動影響，中國人口分布極不平均，其中中國某學者提出一條貫穿中國版圖的假想直線段，該線大致畫出該國人口在區域上的分布，呈現中國人口東南和西北的分布區域之懸殊差異。上述線段大致以哪兩個城市為連線？", "o": ["黑河、騰衝", "漠河、拉薩", "黑河、昆明", "黑河、拉薩"], "a": 0, "e": "這條線是黑河—騰衝線。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-115", "no": 115, "c": "e5", "src": "講義第 35 頁 學習即時通 3-2 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "明清時期，中國部分地區人口快速增加，加上該地區山地丘陵多、耕地不足，導致糧食不足，使不少民眾冒險到海外墾殖。上述這些移民主要墾殖的地區多位於右圖中何處？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "明清閩粵移民主要前往臺灣與東南亞，圖中丁是東南亞。", "rep": false, "img": "g3-q115", "imgnote": "", "fh": "", "maps": ["g3-map-sea"], "chk": ""}, {"id": "g3-116", "no": 116, "c": "e4", "src": "講義第 36 頁 學習即時通 3-3 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "環境負載力的高低受到自然環境影響甚大，右圖為中國四大盆地分布圖，依據圖中資訊判斷，下列哪一盆地的環境負載力可能最高？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "丁是四川盆地，位於季風區、氣候溼潤，環境負載力最高；其他三個盆地在西北乾燥區。", "rep": false, "img": "g3-q116", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-117", "no": 117, "c": "e7", "src": "講義第 36 頁 學習即時通 3-3 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "根據統計資料顯示，2017 年美國的幼年人口性別比為 104，但中國的數值卻高達 117，導致中國數值如此高的原因為何？", "o": ["醫療技術進步", "重男輕女觀念", "人口素質不均", "區域發展失衡"], "a": 1, "e": "中國傳統重男輕女，造成性別比偏高。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-118", "no": 118, "c": "e6", "src": "講義第 36 頁 學習即時通 3-3 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "右圖是中國昔日傳統觀念，由於此一觀念也導致中國出現某種人口問題，中國為了解決問題，提出了列哪一項政策加以因應？「還不清的兒孫債：兒孫滿堂」", "o": ["開放生育二胎", "國民教育普及化", "一胎化政策", "男孩女孩一樣好"], "a": 2, "e": "「兒孫滿堂」生太多，造成人口壓力，中國以一胎化政策因應。", "rep": true, "img": "g3-q118", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-119", "no": 119, "c": "e1", "src": "講義第 37 頁 基礎題 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "中國疆域面積遼闊，各地自然環境不同，傳統第一級產業的維生方式有極大差異，其農業與牧業的分界線位置，大致與下列何者相符？", "o": ["一月月均溫 0℃ 等溫線", "年降水量 250 毫米等雨量線", "年降水量 500 毫米等雨量線", "年降水量 750 毫米等雨量線"], "a": 2, "e": "農業與牧業的分界線大致是年降水量 500mm 等雨量線。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-120", "no": 120, "c": "e2", "src": "講義第 37 頁 基礎題 第 2 題", "st": "講義", "ctx": "", "fig": "圖(一)為高山垂直季節牧業示意圖", "q": "中國疆域面積遼闊，各個地區自然環境不一，傳統賴以維生的產業活動也不盡相同，圖(一)是某地區昔日主要的維生方式，依圖判斷，該地區最可能位於何地？「春天上山吃草、秋天下山避冬」", "o": ["黃土高原", "東南丘陵", "青藏高原", "長江三角洲"], "a": 2, "e": "「春天上山、秋天下山避冬」是山牧季移，在青藏高原。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-121", "no": 121, "c": "e2", "src": "講義第 38 頁 基礎題 第 3 題", "st": "講義", "ctx": "", "fig": "圖(二)為新疆游牧與青藏高原山牧季移對比圖", "q": "中國各地區的居民為了適應不同地形與氣候環境，其傳統維生方式不盡相同，圖(二)呈現的是兩地區的傳統產業，影響兩地出現不同經營模式的主要原因為何？", "o": ["季風風向", "地勢高低", "距海遠近", "技術優劣"], "a": 1, "e": "新疆游牧與青藏高原山牧季移不同，主因是地勢高低。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-122", "no": 122, "c": "e3", "src": "講義第 38 頁 基礎題 第 4 題", "st": "講義", "ctx": "", "fig": "", "q": "如果要利用點圖來呈現現今中國各行政區的人口分布情形，並以同一圖例進行繪製，則下列哪一地形區點的數量可能最多？", "o": ["四川盆地", "青藏高原", "內蒙古高原", "塔里木盆地"], "a": 0, "e": "四川盆地人口最多，點的數量最多。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-123", "no": 123, "c": "e5", "src": "講義第 38 頁 基礎題 第 5 題", "st": "講義", "ctx": "", "fig": "", "q": "明清時期中國哪一地區因山多平原少，加上人口急速增加，糧食供應不足，因此許多民眾為了謀生而遷移到海外，連帶也將漢人文化擴散到移居地？", "o": ["東北沿海", "東南沿海", "西北內陸", "西南內陸"], "a": 1, "e": "明清時期東南沿海山多平原少，人口增加後居民遷往海外。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-sea"], "chk": ""}, {"id": "g3-124", "no": 124, "c": "e3", "src": "講義第 38 頁 基礎題 第 6 題", "st": "講義", "ctx": "", "fig": "圖：西半部面積 57%、人口 6%；東半部面積 43%、人口 94%", "q": "圖(三)所呈現的是中國某種分布情形，依據圖中資訊判斷，東、西半部的分布與下列何者相符？", "o": ["一月 0℃ 等溫線", "黑河及騰衝連線", "南稻北麥分界線", "水田旱田分界線"], "a": 1, "e": "西半部面積 57% 人口 6%、東半部面積 43% 人口 94%，分界是黑河—騰衝線。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-125", "no": 125, "c": "e5", "src": "講義第 38 頁 基礎題 第 7 題", "st": "講義", "ctx": "", "fig": "", "q": "下列哪一敘述最適合用來解釋「文化擴散」的現象？", "o": ["印度的麥當勞因宗教信仰不販售牛肉堡", "東南亞華人聚集處時常可見到漢字招牌", "臺灣傳統布袋戲因觀眾人數少而漸式微", "2020 年初新冠肺炎的疫情在全球蔓延"], "a": 1, "e": "東南亞華人聚集處有漢字招牌，是華人把文化帶到移居地的文化擴散。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-126", "no": 126, "c": "e5", "src": "講義第 38 頁 基礎題 第 8 題", "st": "講義", "ctx": "", "fig": "", "q": "中國東南沿海地區多丘陵地形，平原相對較少，在明清時期中國人口快速成長後，該地區出現糧食不足的現象，使部分居民移居海外，除了臺灣之外，當時該地區的移民多往下列哪一地區遷移？", "o": ["南亞", "北亞", "東南亞", "東北亞"], "a": 2, "e": "明清閩粵移民除了臺灣，多前往東南亞。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-sea"], "chk": ""}, {"id": "g3-127", "no": 127, "c": "e7", "src": "講義第 38 頁 基礎題 第 9 題", "st": "講義", "ctx": "", "fig": "圖(四)為「女孩男孩一樣好」宣傳看板漫畫", "q": "中國建國以來在不同時期推出不同人口政策，習慣用口號宣傳人口政策，圖(四)是該國某一人口標語，依圖判斷，此標語主要是希望改善中國哪一項人口問題？「女孩男孩一樣好」", "o": ["性別比失衡", "人口總數過多", "人口分布不均", "人口高齡化嚴重"], "a": 0, "e": "「女孩男孩一樣好」是為了改善性別比失衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-128", "no": 128, "c": "e6", "src": "講義第 38 頁 基礎題 第 10 題", "st": "講義", "ctx": "", "fig": "", "q": "阿家利用圓餅圖來繪製中國占世界人口的比例，若將圖中粉紅色的部分表示中國人口所占比例，則下列哪一張圖最接近現實狀況？", "o": ["5%", "10%", "20%", "33%"], "a": 2, "e": "中國人口約占世界 1/5，約 20%。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-129", "no": 129, "c": "e4", "src": "講義第 38 頁 基礎題 第 11 題", "st": "講義", "ctx": "", "fig": "圖(五)：甲圖草原上牛羊成群（環境負載力高）；乙圖乾旱草地上只有少數幾隻羊（環境負載力低）。", "q": "圖(五)是老師在解釋環境負載力高低時作為輔助說明的圖示，依據中國地理環境判斷，下列哪一地區相較於其他三者較適合用來作為甲現象的舉例？", "o": ["青藏高原", "內蒙古高原", "塔里木盆地", "長江三角洲"], "a": 3, "e": "甲是環境負載力高，長江三角洲平原廣、雨量多，最適合。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-130", "no": 130, "c": "e7", "src": "講義第 39 頁 基礎題 第 12 題", "st": "講義", "ctx": "", "fig": "圖(六)：一群男孩擠在蹺蹺板的一端，另一端只有一個女孩，中間有一個「性別比」指針。", "q": "圖(六)呈現的是中國某一人口問題，依據該國現況及圖中資訊判斷，圖中指標的數據最可能為下列何者？", "o": ["50", "90", "100", "115"], "a": 3, "e": "中國男多於女，性別比指標大於 100，最可能是 115。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-131", "no": 131, "c": "e5", "src": "講義第 39 頁 精熟題 第 13 題", "st": "講義", "ctx": "", "fig": "", "q": "移民將原鄉文化帶到移居地，使得故鄉文化傳到其他地方的現象稱之為「文化擴散」。其中明清時期中國移民向外擴散的文化最不可能包括下列何者？", "o": ["傳統的媽祖宗教信仰", "以米食為主的飲食文化", "逐水草而居的游牧生活", "生活中農民曆的習俗"], "a": 2, "e": "明清移民來自東南沿海的農業區，不會帶去游牧生活。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-132", "no": 132, "c": "e5", "src": "講義第 39 頁 精熟題 第 14 題", "st": "講義", "ctx": "", "fig": "", "q": "印尼最大的唐人街位於雅加達的草埔（Glodok），草埔知名的建築物金德院，是當地最早的華人寺廟之一。除了印尼之外，許多東南亞國家也有不少華人居住，這些華人的祖先其故鄉原居地的生活方式，與下列何者所描述的最相符？", "o": ["在水草豐美的草原放牧", "冬季在結冰河面上捕魚", "在廣大沙漠綠洲區農耕", "在廣布的丘陵區闢梯田"], "a": 3, "e": "東南亞華人祖先來自閩粵丘陵區，常在山坡開闢梯田。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-133", "no": 133, "c": "e9", "src": "講義第 39 頁 精熟題 第 15 題", "st": "講義", "ctx": "", "fig": "", "q": "右列為某報紙關於知名飲料公司的報導內容，根據內容判斷，中國具備哪一項工業區位的優越條件？「知名飲料公司在中國推出新產品，估計每年購買這個產品的人口會增加 10%，表示會增加約 1.4 億人購買。」", "o": ["市場廣大", "勞工眾多", "動力充足", "原料豐富"], "a": 0, "e": "人口多，產品增加 10% 就有 1.4 億人購買，表示市場廣大。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-134", "no": 134, "c": "e9", "src": "講義第 39 頁 精熟題 第 16 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(七)為中國在不同時期的人口金字塔圖（含預測值），若人口結構依此一趨勢發展，則該段時間的扶養比會呈現何種變化情形？", "o": ["逐漸上升", "逐漸下降", "先升後降", "先降後升"], "a": 3, "e": "1980→2020 壯年比例上升（扶養比下降），2020→2040 壯年比例下降（扶養比上升），先降後升。", "rep": false, "img": "g3-map-pyramid", "imgnote": "附圖以講義〈中國人口金字塔圖〉代替", "fh": "", "maps": [], "chk": ""}, {"id": "g3-135", "no": 135, "c": "e8", "src": "講義第 39 頁 精熟題 第 17 題", "st": "講義", "ctx": "", "fig": "", "q": "「高齡社會」是指老年人口占總人口的比例達 14% 以上，此現象通常出現在經濟發展程度高的國家，如：日本、瑞典等國家，但中國卻在 2021 年就達到高齡社會的標準，此現象與下列何者的關係最密切？", "o": ["曾實施嚴厲的計畫生育政策", "勞動力人口大量流入鄰近國家", "農業人口占總人口比例攀升", "老人安養的相關福利較完善"], "a": 0, "e": "中國快速進入高齡社會，主因是嚴厲的計畫生育（一胎化）政策。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-136", "no": 136, "c": "e5", "src": "講義第 40 頁 精熟題 第 18 題", "st": "講義", "ctx": "", "fig": "", "q": "自明清時期起，中國人口開始快速增加，因人口眾多且分布不均，為尋找更多的耕地或工作機會，有許多中國民眾紛紛向海外遷移，若要利用圖示呈現出該時期中國主要的人口移動路線，則下列哪一張圖最恰當？", "o": ["自東北移往俄羅斯", "自西北移往中亞", "自東南沿海移往臺灣及東南亞", "自華北移往朝鮮半島"], "a": 2, "e": "明清時期人口主要由東南沿海移往臺灣與東南亞，選 (C)。", "rep": true, "img": "g3-q136", "imgnote": "", "fh": "", "maps": ["g3-map-sea"], "chk": ""}, {"id": "g3-137", "no": 137, "c": "e1", "src": "講義第 40 頁 精熟題 第 19 題", "st": "講義", "ctx": "", "fig": "圖(八)為新疆維吾爾自治區輪廓地圖", "q": "中國地形、氣候及產業活動影響人口的分布甚大，且呈現該分布極為不均，圖(八)中灰階行政區的人口集中區多具有下列哪一種特色？", "o": ["屬於平原地勢", "水源供應充足", "海運交通便利", "距海較近地區"], "a": 1, "e": "灰階行政區是新疆，人口集中在水源充足的綠洲、河谷。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-138", "no": 138, "c": "e4", "src": "講義第 40 頁 精熟題 第 20 題", "st": "講義", "ctx": "", "fig": "", "q": "「環境負載力」是一個環境系統能提供的資源及承受干擾、接納穢物的能力；在人口議題上，通常指一地所能供養的人口數。而影響其能力高低的原因包括一地區的自然環境、生產技術及經濟發展。依此判斷，下列哪一地區此能力可能相對較高？", "o": ["青藏高原", "塔里木盆地", "內蒙古高原", "長江三角洲"], "a": 3, "e": "長江三角洲地形平坦、氣候溼潤、經濟發達，環境負載力最高。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-139", "no": 139, "c": "e6", "src": "講義第 40 頁 精熟題 第 21 題", "st": "講義", "ctx": "", "fig": "", "q": "受到嚴格的計畫生育政策影響，中國人口的自然增加率快速下降，由 1980 年的 12‰ 下降到 2020 年的 1‰，但每年增加的人口數仍高達百萬人以上。導致上述現象產生的主要原因為何？", "o": ["移入人口數多", "人口總數眾多", "全無移出人口", "社會增加率高"], "a": 1, "e": "自然增加率雖低，但人口總數眾多，每年增加的人數仍很多。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-140", "no": 140, "c": "e2", "src": "講義第 40 頁 精熟題 第 22 題", "st": "講義", "ctx": "", "fig": "", "q": "居住在數千公尺高原山區的藏族，因為該地區降水相對稀少，空氣稀薄、日夜溫差大，犛牛與山羊成為他們生活中最重要的同伴，藏人運用犛牛毛捻線編織成帳篷，用羊毛做成毛氈地毯與雨衣，而犛牛絨成了珍貴配件。上述族群的維生方式最可能為下列何者？", "o": ["在旱田區種植高粱及小麥", "在水田種需水性高的水稻", "水草豐美的地區放牧牲畜", "春天上山而秋天下山避冬"], "a": 3, "e": "高原山區、春天上山秋天下山避冬，就是山牧季移。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-141", "no": 141, "c": "e6", "src": "講義第 41 頁 精熟題 第 23 題", "st": "講義", "ctx": "", "fig": "圖(九)為中國自然增加率走勢圖", "q": "小敏想寫一篇有關中國人口的文章，圖(九)是她在文章所放的輔助照片，根據圖中內容判斷，中國人口出現此一發展趨勢的主要原因為何？", "o": ["重男輕女觀念盛行", "推行一胎化政策", "環境負載力降低", "勞動人口數減少"], "a": 1, "e": "自然增加率在 1970 年代後大幅下降，主因是推行一胎化政策。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-142", "no": 142, "c": "e1", "src": "講義第 41 頁 精熟題 第 24 題", "st": "講義", "ctx": "", "fig": "", "q": "農業是中國立國根本，但受限於自然環境差異，中國的耕地性質與主要糧食作物有明顯的空間分布差異，此一差異大致與下列哪一氣候界線最相符？", "o": ["一月月均溫 0℃ 等溫線", "一月月均溫 18℃ 等溫線", "年降水量 250mm 等雨量線", "年降水量 500mm 等雨量線"], "a": 0, "e": "耕地（水田旱田）與糧食作物（南稻北麥）的分界，大致和一月均溫 0℃ 等溫線相符。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-143", "no": 143, "c": "e1", "src": "講義第 41 頁 精熟題 第 25 題", "st": "講義", "ctx": "", "fig": "", "q": "近年全球興起一股懷舊旅遊風潮，選擇此類行程的遊客多會體驗在地的傳統生活及飲食，其中黃土高原區特殊的窯洞建築成為熱門的體驗地，遊客到當地時最可能在窯洞附近看到下列何種體驗？", "o": ["望見滾滾長江水流經該地", "與農民一同在水田中插秧", "在陽光底下揮汗收割麥穗", "感受熱帶氣候的炙熱陽光"], "a": 2, "e": "黃土高原在秦嶺、淮河以北，是旱田區，可以收割麥穗。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-144", "no": 144, "c": "e1", "src": "講義第 41 頁 精熟題 第 26 題", "st": "講義", "ctx": "", "fig": "", "q": "第一級產業是中國的傳統產業，受各地區的地形與氣候環境影響，中國第一級產業分布情形與下列哪一張圖最相符？", "o": ["西畜牧區、北旱田區、南水田區", "西水田區、北畜牧區、南旱田區", "西旱田區、北畜牧區、南水田區", "西畜牧區、北水田區、南旱田區"], "a": 0, "e": "中國西部為畜牧區，東部北方旱田、南方水田，選 (A)。", "rep": false, "img": "g3-q144", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-145", "no": 145, "c": "e8", "src": "講義第 41 頁 經典會考題 第 27 題", "st": "講義", "ctx": "", "fig": "表(一)：0～14 歲比例——1953 年 36.28%、1964 年 40.69%、1982 年 33.59%、1990 年 27.69%、2000 年 22.89%、2010 年 16.60%、2020 年 17.95%；65 歲以上——4.41%、3.56%、4.91%、5.57%、6.96%、8.87%、13.50%", "q": "表(一)為中國不同年份的人口普查部分資料。觀察表中幼年人口比例的變動，下列何者最可能是造成 2010 到 2020 年微幅變化的原因之一？", "o": ["開放生育第二胎", "實施一胎化政策", "重男輕女觀念式微", "嚴格限制人口移入"], "a": 0, "e": "2010 到 2020 年幼年人口比例微幅回升，是因為 2015 年開放生育第二胎。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-146", "no": 146, "c": "e8", "src": "講義第 42 頁 經典會考題 第 28 題", "st": "講義", "ctx": "", "fig": "表(二)：甲 1949 年 鼓勵生育；乙 1960 年 提倡晚婚；丙 1979 年 一胎化；丁 2015 年 開放二胎", "q": "表(二)為中國在不同時間提出的人口政策，以因應各階段之需。其中哪一年提出的政策，其目標之一是為了因應老年人口比例逐漸上升所造成的高齡化問題？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "2015 年開放二胎（丁）是為了因應高齡化。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-147", "no": 147, "c": "e9", "src": "講義第 42 頁 經典會考題 第 29 題", "st": "講義", "ctx": "", "fig": "表(三)：全國 2000／2010 年——0～14 歲 22.9%／16.6%，15～64 歲 70.1%／74.5%，65 歲以上 7.0%／8.9%；上海 2000／2010 年——0～14 歲 12.2%／8.6%，15～64 歲 76.3%／81.3%，65 歲以上 11.5%／10.1%", "q": "表(三)為中國全國與上海的常住人口年齡結構，顯示上海的常住人口年齡結構變化趨勢與全國不一致。上述現象與上海的何項特徵關係最密切？", "o": ["房產價格較高", "就業機會較多", "老人福利較佳", "沙塵暴較嚴重"], "a": 1, "e": "上海壯年人口比例高於全國，是因為就業機會多，吸引壯年人口移入。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-148", "no": 148, "c": "e3", "src": "講義第 42 頁 經典會考題 第 30 題", "st": "講義", "ctx": "", "fig": "表(四)：占全國面積／GDP／糧產／人口比例（%）——甲區 56.7／4.3／5.9／6.1；乙區 43.3／95.7／94.1／93.9", "q": "為了了解中國區域發展的差異，曉華將中國畫分為甲區和乙區，並根據 2000 年的資料整理出表(四)。由表中各項數據的比例分配判斷，這二區的分界最可能為下列何者？", "o": ["年均溫 0℃ 等溫線", "黑河與騰衝的連線", "年降水量 750 毫米等雨量線", "東部和中部經濟帶分界線"], "a": 1, "e": "甲區面積 56.7%、人口 6.1%，乙區面積 43.3%、人口 93.9%，分界是黑河—騰衝線。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-149", "no": 149, "c": "e7", "src": "講義第 42 頁 生活時事題組 第 31 題（原為填充題）", "st": "講義", "ctx": "", "fig": "", "q": "中國安徽省有座「光棍村」，其總人口約 1,600 人，約有 112 個年齡 30～55 歲的男子為單身，比例極高。近年來，中國適婚男性找不到結婚對象的問題非常嚴重，雖然中國於 2015 年開放二胎，但性別比失衡問題更加擴大。以安徽省為例，都市出生的第一胎性別比為 109，但第二胎的性別比卻變成 155，農村的第二胎性別比則高達 171，數值都遠高於聯合國規定的 102～107 合理範圍。中國性別比失衡除了與傳統觀念有關之外，還與曾實施哪一項人口政策有關？", "o": ["一胎化政策", "三孩政策", "兩免一補", "知青下鄉"], "a": 0, "e": "性別比失衡除了重男輕女，也和 1979 年起的一胎化政策有關。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-150", "no": 150, "c": "e7", "src": "講義第 42 頁 生活時事題組 第 32 題", "st": "講義", "ctx": "中國安徽省有座「光棍村」，其總人口約 1,600 人，約有 112 個年齡 30～55 歲的男子為單身，比例極高。近年來，中國適婚男性找不到結婚對象的問題非常嚴重，雖然中國於 2015 年開放二胎，但性別比失衡問題更加擴大。以安徽省為例，都市出生的第一胎性別比為 109，但第二胎的性別比卻變成 155，農村的第二胎性別比則高達 171，數值都遠高於聯合國規定的 102～107 合理範圍。", "fig": "", "q": "依據上文內容判斷，中國的性別比情形與下列哪一張圖最相符？", "o": ["男女各半", "全部是男", "男多於女", "女多於男"], "a": 2, "e": "性別比遠高於 100，男多於女，選男生占比較大的 (C)。", "rep": false, "img": "g3-q150", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-151", "no": 151, "c": "e3", "src": "講義第 43 頁 閱讀素養題組 第 33 題", "st": "講義", "ctx": "", "fig": "", "q": "中國春運是指在春節期間發生的大規模高交通運輸壓力的現象，被認為是人類歷史上規模最大的週期性遷徙活動。中國每年春運時間以春節為中心，開始於春節前 15 天，春節後 25 天，共計 40 天。每年約有超過 2.2 億人在此期間移動，而由於中國人口分布不均，以某連線為界，該線東半部面積僅占全國 43%，卻聚集全國 94% 的人口，其中此區的沿海地帶經濟發展早，工作與就學機會多，因此春節前返鄉過節人潮也相對較多，連帶影響各地區人口流動呈現不均的現象。文中提及春運期間人口流動呈現不均的現象，與下列哪一句話所描述的最相符？", "o": ["東南熱、西北冷", "東南冷、西北熱", "西南熱、東北冷", "西南冷、東北熱"], "a": 0, "e": "東南沿海人口多、外出工作的人多，春運人潮大；西北人口少，所以東南熱、西北冷。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-152", "no": 152, "c": "e9", "src": "講義第 43 頁 閱讀素養題組 第 34 題", "st": "講義", "ctx": "中國春運是指在春節期間發生的大規模高交通運輸壓力的現象，被認為是人類歷史上規模最大的週期性遷徙活動。中國每年春運時間以春節為中心，開始於春節前 15 天，春節後 25 天，共計 40 天。每年約有超過 2.2 億人在此期間移動，而由於中國人口分布不均，以某連線為界，該線東半部面積僅占全國 43%，卻聚集全國 94% 的人口，其中此區的沿海地帶經濟發展早，工作與就學機會多，因此春節前返鄉過節人潮也相對較多，連帶影響各地區人口流動呈現不均的現象。", "fig": "", "q": "依據中國人的習俗判斷，春節前 15 天由圖(十)中的哪一行政區移出的人口數可能最多？", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "春節前是回鄉，人口從工作機會多的沿海地區移出，丙（廣東）移出最多。", "rep": false, "img": "g3-q152", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-153", "no": 153, "c": "e3", "src": "講義第 43 頁 閱讀素養題組 第 35 題", "st": "講義", "ctx": "中國春運是指在春節期間發生的大規模高交通運輸壓力的現象，被認為是人類歷史上規模最大的週期性遷徙活動。中國每年春運時間以春節為中心，開始於春節前 15 天，春節後 25 天，共計 40 天。每年約有超過 2.2 億人在此期間移動，而由於中國人口分布不均，以某連線為界，該線東半部面積僅占全國 43%，卻聚集全國 94% 的人口，其中此區的沿海地帶經濟發展早，工作與就學機會多，因此春節前返鄉過節人潮也相對較多，連帶影響各地區人口流動呈現不均的現象。", "fig": "", "q": "文中提及某連線（黑河—騰衝線）與下列哪一張圖所呈現的最相符？", "o": ["從東北斜向西南的直線", "從西北斜向東南的直線", "從西南往東北的平緩斜線", "橫貫東西的直線"], "a": 0, "e": "黑河—騰衝線是從東北斜向西南的直線，選 (A)。", "rep": false, "img": "g3-q153", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-154", "no": 154, "c": "e1", "src": "評量單 第 5 回 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "農業是中國立國基礎，該國主要農業活動多分布於圖(一)中哪一地區？", "o": ["甲", "乙", "丙", "丁"], "a": 0, "e": "甲位於東部季風區，是主要農業區。", "rep": false, "img": "g3-q154", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-155", "no": 155, "c": "e1", "src": "評量單 第 5 回 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "阿敏利用三月到中國東南方的廣東及福建一帶旅遊，下列何者最可能是她在當地所見到的景象？", "o": ["旱田中低垂的麥穗", "採山牧季移的牧民", "沙漠中的游牧民族", "水田中嫩綠的稻苗"], "a": 3, "e": "廣東、福建在秦嶺淮河以南，三月可看到水田中的稻苗。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-156", "no": 156, "c": "e1", "src": "評量單 第 5 回 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國自古以農立國，但傳統農業活動受自然環境的限制大，因此出現顯著的區域差異，下列何者是中國農業發展的現象？", "o": ["東農西牧、北旱田南水田", "東牧西農、北旱田南水田", "東農西牧、北水田南旱田", "東牧西農、北水田南旱田"], "a": 0, "e": "中國農業為東農西牧，東部農業區又分北旱田、南水田。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-157", "no": 157, "c": "e1", "src": "評量單 第 5 回 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國西北內陸的居民多以牧業維生，其主要原因為何？", "o": ["地勢較高", "人口較少", "技術較差", "降水較少"], "a": 3, "e": "西北內陸距海遠、降水少，只能以畜牧維生。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-158", "no": 158, "c": "e2", "src": "評量單 第 5 回 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "「為了提升產量，中國某一以畜牧業為主的行政區近年利用科技化的方式管理乳牛飼養場……。」上文中提及的行政區應為圖(二)中何者？", "o": ["甲", "乙", "丙", "丁"], "a": 0, "e": "甲是內蒙古，以畜牧業為主。", "rep": false, "img": "g3-q158", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-159", "no": 159, "c": "e1", "src": "評量單 第 5 回 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國人口分布極不平均，其中農業區的人口數量遠高於畜牧區，影響畜牧區人口較為稀少的主要因素為何？", "o": ["地形較崎嶇", "水源較缺乏", "年均溫較高", "鄰國戰事多"], "a": 1, "e": "畜牧區乾燥少雨，水源缺乏，人口稀少。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-160", "no": 160, "c": "e1", "src": "評量單 第 5 回 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國西部內陸地區降水較少，除了河谷、綠洲因甲因素有種植作物外，傳統以畜牧維生。上述甲因素應為下列何者？", "o": ["距海較近", "季風強勁", "水源較豐", "緯度較低"], "a": 2, "e": "河谷、綠洲有水源，才能種植作物。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-161", "no": 161, "c": "e3", "src": "評量單 第 5 回 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "通常一地的人口受自然環境的影響，愈適合生產糧食的地方，其人口密度愈高，反之則密度較低。依此判斷，下列哪一地區的人口密度最低？", "o": ["四川盆地", "東南丘陵", "長江三角洲", "內蒙古高原"], "a": 3, "e": "內蒙古高原乾燥、以畜牧為主，人口密度最低。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-162", "no": 162, "c": "e2", "src": "評量單 第 5 回 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "某畜牧方式是配合高山海拔高低的氣溫差異所形成，通常牧民在春天驅趕牲畜上山吃草，到秋天則驅趕牲畜下山避冬。上述的畜牧方式最可能出現在哪一地區？", "o": ["福建省", "北京市", "黑龍江省", "西藏自治區"], "a": 3, "e": "山牧季移出現在高山、高原地區，例如西藏。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-163", "no": 163, "c": "e1", "src": "評量單 第 5 回 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國各地居民為了適應不同地形與氣候，其傳統維生方式有顯著的空間差異，其中農業與畜牧業的分界線與下列何者最相符？", "o": ["一月月均溫 0℃ 等溫線", "一月月均溫 18℃ 等溫線", "年降水量 500mm 等雨量線", "年降水量 750mm 等雨量線"], "a": 2, "e": "農牧分界線大致是年降水量 500mm 等雨量線。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-164", "no": 164, "c": "e5", "src": "評量單 第 6 回 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "西元 17 至 19 世紀時，有許多原居於中國的民眾向海外墾殖，當時移出的地區除了臺灣之外，主要集中在下列哪一地區？", "o": ["北亞", "南亞", "東北亞", "東南亞"], "a": 3, "e": "17～19 世紀的中國移民，除了臺灣，主要去東南亞。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-sea"], "chk": ""}, {"id": "g3-165", "no": 165, "c": "e6", "src": "評量單 第 6 回 第 2 題", "st": "考卷", "ctx": "", "fig": "圖(一)為兒孫滿堂背負沉重家庭負擔之漫畫", "q": "圖(一)是中國昔日傳統社會的家庭觀念，中國為了改善此一狀況，提出下列哪一項措施來因應？「還不清的兒孫債」", "o": ["一胎化政策", "宣導男孩女孩一樣好", "普及教育政策", "推經濟改革開放措施"], "a": 0, "e": "「兒孫滿堂」人口過多，中國以一胎化政策控制人口。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-166", "no": 166, "c": "e7", "src": "評量單 第 6 回 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "2024 年中國的新生兒性別比為 109，此一數據所代表的意義為何？", "o": ["男性比女性多", "男女比例相差不多", "女性比男性多", "老年及幼年人口少"], "a": 0, "e": "性別比 109 表示每 100 名女嬰對 109 名男嬰，男性比女性多。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-sex"], "chk": ""}, {"id": "g3-167", "no": 167, "c": "e4", "src": "評量單 第 6 回 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "環境負載力會影響一地區的人口密度，依據中國的自然環境判斷，圖(二)中哪一地區的環境負載力最高？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "丁是四川盆地，氣候溼潤、農業發達，環境負載力最高。", "rep": false, "img": "g3-q167", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-168", "no": 168, "c": "e5", "src": "評量單 第 6 回 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "「唐人街」是指華人地區以外國家的城市裡華裔人士的聚居區，唐人街因歷史因素或特殊國情在下列哪一國家境內出現的機會相對較大？", "o": ["北亞", "西亞", "中亞", "東南亞"], "a": 3, "e": "東南亞華人最多，最容易出現唐人街。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-169", "no": 169, "c": "e3", "src": "評量單 第 6 回 第 6 題", "st": "考卷", "ctx": "", "fig": "圖：西半部面積 57%、人口 6%；東半部面積 43%、人口 94%", "q": "圖(三)為中國人口分布示意圖，其中畫分東西半部連線為何？", "o": ["漠河—騰衝", "漠河—昆明", "黑河—昆明", "黑河—騰衝"], "a": 3, "e": "東西半部的分界線是黑河—騰衝線。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-170", "no": 170, "c": "e6", "src": "評量單 第 6 回 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國政府為了控制人口成長的速度，曾推出計畫生育政策，實施後雖降低自然增加率，但每年增加的人口數仍相當驚人，導致上述情形產生的主要原因為何？", "o": ["移入人口多", "人口總數多", "糧食產量高", "經濟成長快"], "a": 1, "e": "自然增加率雖降低，但人口總數多，每年增加的人數仍很驚人。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-171", "no": 171, "c": "e6", "src": "評量單 第 6 回 題組 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(四)是中國人口金字塔變化圖，產生圖中人口結構變遷的主要原因為何？", "o": ["出生率下降", "死亡率上升", "移入率上升", "移出率下降"], "a": 0, "e": "金字塔底部大幅收縮，主因是出生率下降。", "rep": false, "img": "g3-map-pyramid", "imgnote": "附圖以講義〈中國人口金字塔圖〉代替", "fh": "", "maps": [], "chk": ""}, {"id": "g3-172", "no": 172, "c": "e9", "src": "評量單 第 6 回 題組 第 9 題", "st": "考卷", "ctx": "圖(四)是中國 1980、2020、2040 年的人口金字塔變化圖。", "fig": "", "q": "承上題，由 1980 年到 2040 年間的人口扶養比呈現何種變遷趨勢？", "o": ["持續下降", "持續上升", "先升後降", "先降後升"], "a": 3, "e": "1980→2020 扶養比下降，2020→2040 扶養比上升，先降後升。", "rep": false, "img": "g3-map-pyramid", "imgnote": "附圖以講義〈中國人口金字塔圖〉代替", "fh": "", "maps": [], "chk": ""}, {"id": "g3-173", "no": 173, "c": "e8", "src": "評量單 第 6 回 題組 第 10 題", "st": "考卷", "ctx": "圖(四)是中國 1980、2020、2040 年的人口金字塔變化圖。", "fig": "", "q": "若中國的人口依此趨勢發展下去，則未來中國可能會面臨的問題不包括下列何者？", "o": ["少子化", "人口高齡化", "人口素質下降", "勞動力人口降低"], "a": 2, "e": "少子化、高齡化、勞動力降低都會發生，但看不出人口素質下降。", "rep": false, "img": "g3-map-pyramid", "imgnote": "附圖以講義〈中國人口金字塔圖〉代替", "fh": "", "maps": [], "chk": ""}, {"id": "g3-174", "no": 174, "c": "e1", "src": "試題寶典評量 第 22 頁 選擇題 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國有句俗諺：「山北黃牛下地，山南水牛犁田」，黃牛適合在旱田耕作，水牛適合在水田耕作。根據上述內容判斷，文中的「山」應是下列何者？", "o": ["秦嶺", "黃土高原", "東南丘陵", "喜馬拉雅山"], "a": 0, "e": "山北黃牛耕旱田、山南水牛耕水田，這座山是秦嶺。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-175", "no": 175, "c": "e1", "src": "試題寶典評量 第 22 頁 選擇題 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國因受自然環境差異的影響，傳統維生方式通常因地制宜。圖(一)中何地的農業集中於河谷、綠洲地帶？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "丁位於新疆，乾燥少雨，農業集中在河谷、綠洲。", "rep": false, "img": "g3-q175", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-176", "no": 176, "c": "e1", "src": "試題寶典評量 第 22 頁 選擇題 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國傳統的農牧業可依據下列何種條件，大致分成東半部和西半部兩大部分？", "o": ["最冷月月均溫 0℃ 等溫線", "最冷月月均溫 18℃ 等溫線", "年降水量 250 mm 等雨量線", "年降水量 500 mm 等雨量線"], "a": 3, "e": "東農西牧以年降水量 500mm 等雨量線為界。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-177", "no": 177, "c": "e2", "src": "試題寶典評量 第 22 頁 選擇題 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(二)為中國某地區的畜牧方式。此種畜牧方式最可能分布在圖(三)的哪一地區？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "圖(二)是山牧季移，出現在青藏高原，圖(三)中的丁。", "rep": false, "img": "g3-q177", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-178", "no": 178, "c": "e2", "src": "試題寶典評量 第 22 頁 選擇題 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "內蒙古高原的西部以游牧為主，青藏高原則以山牧季移為主。上述兩個地區畜牧方式不同，主要是受到下列哪個因素的影響？", "o": ["地形起伏", "年溫差大小", "季風風向", "緯度高低"], "a": 0, "e": "內蒙古高原西部游牧、青藏高原山牧季移，主因是地形起伏（海拔高低）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-179", "no": 179, "c": "e5", "src": "試題寶典評量 第 22 頁 選擇題 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國東南沿海地區人口稠密，部分居民渡海來臺灣開墾，這些人口遷移時間主要為下列何者？", "o": ["隋唐時期", "宋元時期", "明清時期", "民國初期"], "a": 2, "e": "東南沿海居民大量渡海來臺開墾，是在明清時期。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-180", "no": 180, "c": "e5", "src": "試題寶典評量 第 22 頁 選擇題 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "人們為了生計離開家鄉，造成人口的國內或國際遷移。移民者將原鄉文化帶到移居地，呈現何種文化現象？", "o": ["文化融合", "文化傳承", "文化創新", "文化擴散"], "a": 3, "e": "移民把原鄉文化帶到移居地，稱為文化擴散。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-181", "no": 181, "c": "e3", "src": "試題寶典評量 第 22 頁 選擇題 第 8 題", "st": "考卷", "ctx": "", "fig": "圖：西半部面積 57%、人口 6%；東半部面積 43%、人口 94%", "q": "圖(四)為中國某人口問題示意圖，其最能反映出下列哪項人口問題？", "o": ["人口成長快速", "人口分布不均", "人口素質低落", "人口組成失衡"], "a": 1, "e": "西半部面積大、人口少；東半部面積小、人口多，反映人口分布不均。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-182", "no": 182, "c": "e5", "src": "試題寶典評量 第 22 頁 選擇題 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "明清時期，福建、廣東一帶因地狹人稠，不少居民被迫向海外謀生。他們在移居地經商、務農，保留了漢人飲食與節慶習俗，形成當地重要的華人社群。上述移民最可能移居到哪個地區？", "o": ["南亞", "東南亞", "東北亞", "中南美洲"], "a": 1, "e": "明清閩粵居民主要移居東南亞。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-sea"], "chk": ""}, {"id": "g3-183", "no": 183, "c": "e1", "src": "試題寶典評量 第 23 頁 選擇題 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國西半部人口稀疏，大多集中在少數的綠洲和河谷。上述地理現象與下列哪一因素關係最密切？", "o": ["地形較平坦", "土壤較肥沃", "水源較豐富", "交通較便利"], "a": 2, "e": "西半部乾燥，人口集中在水源豐富的綠洲、河谷。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-184", "no": 184, "c": "e6", "src": "試題寶典評量 第 23 頁 選擇題 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "2023 年全球人口已突破 80 億人。曉玲想利用圓餅圖繪製中國與全球人口比例的關係，紫色區塊表示中國人口比例，則下列哪一張圖最接近實際情況？", "o": ["5%", "10%", "20%", "33%"], "a": 2, "e": "中國約 14 億、全球約 80 億，約占 1/5，選 20%。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-185", "no": 185, "c": "e6", "src": "試題寶典評量 第 23 頁 選擇題 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "1979 年起，中國政府實施人口政策，其目的是要在短時間內達到下列哪一目的？", "o": ["降低出生率", "增加死亡率", "降低移入率", "增加移出率"], "a": 0, "e": "一胎化的目的是降低出生率，控制人口成長。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-186", "no": 186, "c": "e8", "src": "試題寶典評量 第 23 頁 選擇題 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "根據 2023 年的統計，中國老年人口約占總人口 16%，已邁入高齡社會。導致中國人口出現上述現象，除了一胎化政策外，主要與下列哪項因素有關？", "o": ["醫療衛生進步", "環境品質改善", "飲食結構改變", "國民所得提高"], "a": 0, "e": "高齡化除了一胎化（幼年人口減少），還因醫療衛生進步，壽命延長。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-187", "no": 187, "c": "e8", "src": "試題寶典評量 第 23 頁 選擇題 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "1979 年起，中國實施人口政策，對於目前中國的人口有何影響？", "o": ["失業率逐漸上升", "人口組成高齡化", "人口總數迅速減少", "人口分布更加不均"], "a": 1, "e": "一胎化使幼年人口減少，人口組成快速高齡化。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-188", "no": 188, "c": "e9", "src": "試題寶典評量 第 23 頁 選擇題 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國於 2015 年宣布「結束一胎化政策，開放生育二胎」，並鼓勵生育。這種人口政策的轉變，主要是為了因應即將面臨的何種人口問題？", "o": ["人口密度下降", "失業人口增加", "勞動力人口減少", "流動人口眾多"], "a": 2, "e": "開放二胎是擔心少子化造成勞動力人口減少。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-189", "no": 189, "c": "e5", "src": "試題寶典評量 第 23 頁 精熟題 第 1 題", "st": "考卷", "ctx": "", "fig": "圖(五)為東南沿海向臺灣及東南亞航向之箭頭圖", "q": "圖(五)為中國東南沿海地區早期某種現象的示意圖，圖中「→」最有可能是下列哪一種現象？", "o": ["茶葉外銷", "稻米出口", "礦產輸出", "人口遷移"], "a": 3, "e": "箭頭從東南沿海指向臺灣、東南亞，是人口遷移。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-sea"], "chk": ""}, {"id": "g3-190", "no": 190, "c": "e8", "src": "試題寶典評量 第 23 頁 精熟題 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "根據中國人口年齡組成的變遷趨勢，以圖(六)中三幅人口金字塔圖來表示過去到未來的變化，其順序應為下列何者？", "o": ["甲→乙→丙", "甲→丙→乙", "乙→丙→甲", "丙→甲→乙"], "a": 3, "e": "過去到未來：丙（底寬，增加型）→甲→乙（底窄，縮減型），順序丙→甲→乙。", "rep": true, "img": "g3-q190", "imgnote": "", "fh": "", "maps": ["g3-map-pyramid"], "chk": ""}, {"id": "g3-191", "no": 191, "c": "e3", "src": "試題寶典評量 第 24 頁 精熟題 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "學者在研究世界人口分布時，常會以夜間用電量做為重要指標，人口稠密的地區在衛星照片下呈現一片光亮，而人口稀少的地區則經常是漆黑一片。圖(七)中何處夜間較無光害，是中國可清楚看見滿天星斗的最佳地點之一？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "丁位於西部（青藏地區），人口稀少、夜間燈光少，最能看見星空。", "rep": false, "img": "g3-q191", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-192", "no": 192, "c": "e8", "src": "試題寶典評量 第 24 頁 精熟題 第 4 題", "st": "考卷", "ctx": "", "fig": "表(一)：0～14 歲／15～64 歲／65 歲以上（%）——甲 15.1／73.1／11.8；乙 13.6／72.8／13.6；丙 17.6／66.1／16.3；丁 10.7／69.1／20.2", "q": "一胎化政策使中國幼年人口比例減少，加上醫療衛生進步讓壽命延長，老年人口比例逐漸增加。2023 年，中國已邁入高齡社會。根據上文判斷，該年中國的年齡組成最可能為表(一)中何者？", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "2023 年中國老年人口約占 16%，已是高齡社會（≥14%）但還不到超高齡（≥20%），四組中丙（16.3%）最符合，丁（20.2%）已是超高齡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-193", "no": 193, "c": "e5", "src": "試題寶典評量 第 24 頁 精熟題 第 5 題", "st": "考卷", "ctx": "", "fig": "圖(八)標註福建、廣東為「華人外移原鄉」之地圖", "q": "舊金山唐人街自 1840 年代成立以來，一直是美國華人移民歷史和文化中重要的一部分。圖(八)中的「華人外移原鄉」也是舊金山華人早期的移民原鄉，根據圖中位置判斷，華人離開原鄉向外冒險的主要原因為何？", "o": ["山多田少，人口眾多", "位置偏僻，交通不便", "多水旱災，民不聊生", "政治紛擾，經濟蕭條"], "a": 0, "e": "福建、廣東山多田少、人口眾多，居民只好向外冒險謀生。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-sea"], "chk": ""}, {"id": "g3-194", "no": 194, "c": "e8", "src": "試題寶典評量 第 24 頁 精熟題 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "「中國大量的人口成為產業發展助力，但人口若超過環境負載力時，人口壓力將成為發展的阻力，除此之外，還有人力資源不足的隱憂。」依據上述「隱憂」判斷，下列哪項口號最適合作為目前中國政府的人口政策？", "o": ["兩個孩子恰恰好，一個孩子不嫌少", "兩個孩子很幸福，三個孩子更熱鬧", "少生孩子多種樹，少養孩子多養豬", "男孩女孩一樣好，關愛民族的未來"], "a": 1, "e": "隱憂是人力資源不足，要鼓勵生育，選鼓勵生三個孩子的口號 (B)。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-195", "no": 195, "c": "e7", "src": "試題寶典評量 第 24 頁 精熟題 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國性別比長期失衡，導致近年來「剩男」、「光棍節」等名詞蔚為流行，造成這種現象的主要原因，除了曾實施一胎化政策外，還與下列哪項關係最密切？", "o": ["醫療技術進步", "重男輕女觀念", "教育水準提高", "飲食習慣改變"], "a": 1, "e": "剩男、光棍問題除了一胎化，主要與重男輕女觀念有關。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-196", "no": 196, "c": "e6", "src": "試題寶典評量 第 25 頁 精熟題 第 8 題", "st": "考卷", "ctx": "", "fig": "表(二)：出生率／死亡率／人口增加率（‰）／人口增加數（千人）——甲 12.2／6.9／5／6,650；乙 13.8／8.4／8／2,474；丙 17.3／6.0／11／985；丁 29.4／4.9／24／712", "q": "表(二)是明哲蒐集部分國家 2010 年的人口資料。觀察表中行最下方一列的數據，甲國明顯大於其他國家，推論其原因，下列何者最合理？", "o": ["醫療條件較為優越", "移入率大於移出率", "施行獎勵生育政策", "人口總數較為龐大"], "a": 3, "e": "甲國自然增加率只有 5‰ 但增加人數最多，是因為人口總數龐大。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-197", "no": 197, "c": "e4", "src": "試題寶典評量 第 25 頁 精熟題 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "「環境負載力」是指一個環境系統所能提供能源、物質以及分解穢物的能力。環境負載力高之處，人口稠密；環境負載力低之處，人口稀疏。根據上述定義判斷，若要利用此一指標將中國進行環境負載力高低的劃分，下列何者最符合？", "o": ["北高南低", "西高東低", "西北低、東南高", "西北高、東南低"], "a": 2, "e": "依原卷選項，(C)「西北低、東南高」最符合：東南部環境負載力高、人口稠密，西北部低、人口稀疏。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-198", "no": 198, "c": "e8", "src": "試題寶典評量 第 25 頁 精熟題 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "「根據中國地方政府公告以及《中國統計年鑑》的數據，截至 2021 年底，中國有 16 個省（市）人口數量較 2020 年底減少；有 11 個省（市）出生率低於死亡率。」上述資料最能反映出下列哪項人口問題？", "o": ["人口數量太多", "人口分布不均", "人口素質低落", "人口老化嚴重"], "a": 3, "e": "多個省分人口減少、出生率低於死亡率，表示人口老化嚴重。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-199", "no": 199, "c": "e6", "src": "試題寶典評量 第 25 頁 精熟題 第 11 題", "st": "考卷", "ctx": "", "fig": "圖(九)為兒孫滿堂漫畫", "q": "圖(九)是某中國政策的宣導漫畫圖，依圖中內容判斷，此宣導是為了解決中國哪一項人口問題？「還不清的兒孫債」", "o": ["人口數量龐大", "人口分布不均", "流動人口眾多", "性別組成失衡"], "a": 0, "e": "「還不清的兒孫債」諷刺生太多，宣導目的是解決人口數量龐大。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-200", "no": 200, "c": "e7", "src": "試題寶典評量 第 25 頁 精熟題 第 12 題", "st": "考卷", "ctx": "", "fig": "表(三)：甲 1949 年 鼓勵生育；乙 1979 年 一胎化；丙 2015 年 開放生育二胎；丁 2021 年 通過三孩政策", "q": "表(三)為中國在不同時間提出的人口政策，以因應各階段之需。根據表中資料判斷，其中哪一項政策造成性別比失衡？", "o": ["甲", "乙", "丙", "丁"], "a": 1, "e": "乙（1979 年一胎化）加上重男輕女，造成性別比失衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-201", "no": 201, "c": "e8", "src": "試題寶典評量 第 25 頁 精熟題 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "「421 家庭」是因中國人口政策而產生的現象，即家庭由 4 名祖父母、2 名父母和 1 名子女組成。根據上述內容判斷，中國未來將面臨何種現象？", "o": ["失業率下降", "性別比失衡", "扶養比提高", "勞動力增加"], "a": 2, "e": "421 家庭表示一個孩子要扶養多位長輩，扶養比提高。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-202", "no": 202, "c": "e3", "src": "試題寶典評量 第 26 頁 精熟題 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "2019 年底，中國出現新冠肺炎疫情，而 2020 年農曆新年，大量民眾返鄉過年，導致疫情迅速擴散，但確診病例分布差異大，東半部病例數特別多，而西半部病例數較少。東半部和西半部確診病例數的差異，最能反映出何種人口現象？", "o": ["人口密度", "人口結構", "人口素質", "人口遷移"], "a": 0, "e": "東半部人口密度高，病毒容易傳播；西半部人口密度低，病例少。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-203", "no": 203, "c": "e7", "src": "試題寶典評量 第 26 頁 精熟題 第 15 題", "st": "考卷", "ctx": "", "fig": "表(四)：新生兒性別比——陳家村 118、林家村 106、李家村 122、蔡家村 98", "q": "中國傳統習俗上，若生男嬰時，要準備油飯分送給親友。表(四)為四個村莊 2020 年的新生兒性別比資料，假設四個村莊同時有 500 戶人家添增一名新生兒，依表中資料推測，哪個村莊製作油飯的戶數最多？", "o": ["陳家村", "林家村", "李家村", "蔡家村"], "a": 2, "e": "油飯是生男嬰才送，性別比最高（122）的李家村男嬰最多。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-sex"], "chk": ""}, {"id": "g3-204", "no": 204, "c": "e7", "src": "試題寶典評量 第 26 頁 精熟題 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "新聞報導：「每年巴基斯坦有超過 600 名女孩被賣到中國，緬甸有超過 2 萬名女孩被迫嫁到中國，這使中國連續 3 年被全球防制人口販運評比列入最差國家，外媒分析此現象是一胎化的影響。」上文凸顯中國的何種人口問題？", "o": ["人口分布不均", "勞動力不足", "性別比嚴重失衡", "邁入高齡化社會"], "a": 2, "e": "女孩被賣到中國當新娘，表示中國男多女少，性別比嚴重失衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-205", "no": 205, "c": "e9", "src": "試題寶典評量 第 26 頁 精熟題 第 17 題", "st": "考卷", "ctx": "", "fig": "表(五)：全國 2000／2010 年——0～14 歲 22.9%／16.6%，15～64 歲 70.1%／74.5%，65 歲以上 7.0%／8.9%；上海 2000／2010 年——0～14 歲 12.2%／8.6%，15～64 歲 76.3%／81.3%，65 歲以上 11.5%／10.1%", "q": "表(五)為中國全國與上海的常住人口年齡結構，顯示上海的常住人口年齡結構變化趨勢與全國不一致。上述現象與上海的何項特徵關係最密切？", "o": ["房產價格較高", "就業機會較多", "老人福利較佳", "沙塵暴較嚴重"], "a": 1, "e": "上海壯年人口比例上升，是因為就業機會多，吸引壯年人口移入。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-206", "no": 206, "c": "e2", "src": "試題寶典評量 第 26 頁 精熟題 第 18 題", "st": "考卷", "ctx": "", "fig": "圖(十)：由北而南穿過崑崙山、唐古拉山到喜馬拉雅山的地形剖面圖，甲區海拔約 4,000～5,000 公尺，地勢高而起伏。", "q": "圖(十)為中國某地區的地形剖面圖，依據圖中的高度和地表起伏狀態判斷，在甲區最有可能出現下列哪種地理景象？", "o": ["辛勤的水牛在耕作", "小麥田的豐收景觀", "大草原的游牧生活", "山牧季移的犛牛群"], "a": 3, "e": "甲區海拔超過 4000 公尺，是青藏高原，會看到山牧季移的犛牛群。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-207", "no": 207, "c": "e8", "src": "試題寶典評量 第 26 頁 精熟題 第 19 題", "st": "考卷", "ctx": "", "fig": "表(六)：0～14 歲比例——1990 年 27.69%、2000 年 22.89%、2010 年 16.60%、2020 年 17.95%", "q": "表(六)為中國不同年份的人口普查部分資料。觀察表中幼年人口比例的變動，下列何者最可能是造成 2010 年到 2020 年微幅變化的原因之一？", "o": ["開放生育第二胎", "實施一胎化政策", "重男輕女觀念式微", "嚴格限制人口移入"], "a": 0, "e": "2010 到 2020 年幼年人口比例微幅回升，是因為開放生育第二胎。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-208", "no": 208, "c": "e6", "src": "試題寶典評量 第 27 頁 精熟題 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "近年中國許多大都市的教育機構，開設幼兒 MBA 課程，主要在啟發幼童的思考力及創造力。中國許多父母擔憂孩子未來社會競爭激烈，主要源自於中國人口的何種特色？", "o": ["人口數量龐大", "人口組成失衡", "人口素質較低", "流動人口眾多"], "a": 0, "e": "人口數量龐大，社會競爭激烈，父母才讓孩子從小補習。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-209", "no": 209, "c": "e8", "src": "試題寶典評量 第 27 頁 素養UP題組 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國為了降低人口成長壓力，於 1970 年代開始推動生育計畫，1979 年更通過實施「一胎化政策」，遵行政策的夫妻會得到經濟或就業上的獎勵，超育的夫妻則會遭到處罰。中國實施 30 多年的「一胎化政策」，造成人口組成呈現何種現象？", "o": ["多子化與高齡化", "少子化與高齡化", "多子化與幼齡化", "少子化與幼齡化"], "a": 1, "e": "一胎化使孩子變少（少子化），老年人比例相對提高（高齡化）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-210", "no": 210, "c": "e8", "src": "試題寶典評量 第 27 頁 素養UP題組 第 2 題", "st": "考卷", "ctx": "中國為了降低人口成長壓力，於 1970 年代開始推動生育計畫，1979 年更通過實施「一胎化政策」，遵行政策的夫妻會得到經濟或就業上的獎勵，超育的夫妻則會遭到處罰。", "fig": "", "q": "承上題，圖(一)為中國生育率統計圖，根據上文所提供的資料判斷，中國在哪個年代以後，呈現「超低生育率」的現象？", "o": ["1970 年", "1980 年", "1990 年", "2000 年"], "a": 3, "e": "中國生育率在 2000 年左右降到 1.5 以下，所以 2000 年以後是超低生育率。", "rep": false, "img": "g3-q210", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-211", "no": 211, "c": "e1", "src": "試題寶典評量 第 27 頁 素養UP題組 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國昔日以農立國，但隨著經濟發展，農業的比重降低。圖(二)為中國農牧業產業活動分布簡圖。圖中的「ㄅ」線是分隔農業區與畜牧區的分界線，該線大致和下列哪種氣候的等值線位置相符？", "o": ["500 毫米年降水量線", "750 毫米年降水量線", "一月均溫 0℃ 等溫線", "七月均溫 20℃ 等溫線"], "a": 0, "e": "「ㄅ」線分隔農業區與畜牧區，大致是年降水量 500mm 線。", "rep": false, "img": "g3-q211", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-212", "no": 212, "c": "e1", "src": "試題寶典評量 第 27 頁 素養UP題組 第 4 題", "st": "考卷", "ctx": "中國昔日以農立國，但隨著經濟發展，農業的比重降低。圖(二)為中國農牧業產業活動分布簡圖。", "fig": "", "q": "承上題，畫分圖中甲、乙兩區的地理界線，其位置大致與下列哪組地理現象的分界線符合？", "o": ["欄牧區與放牧區的界線", "多水田與多旱田的界線", "小麥區和高粱區的界線", "水稻農業區和綠洲農業區的界線"], "a": 1, "e": "甲（北方）多旱田、乙（南方）多水田，分界是秦嶺、淮河。", "rep": false, "img": "g3-q211", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-213", "no": 213, "c": "e2", "src": "試題寶典評量 第 27 頁 素養UP題組 第 5 題", "st": "考卷", "ctx": "中國昔日以農立國，但隨著經濟發展，農業的比重降低。圖(二)為中國農牧業產業活動分布簡圖。", "fig": "", "q": "承上題，圖中的畜牧區可分為游牧、放牧與垂直移動的山牧季移。而山牧季移最可能分布在下列哪種氣候類型？", "o": ["氣候圖 (A)", "氣候圖 (B)", "氣候圖 (C)", "氣候圖 (D)"], "a": 2, "e": "山牧季移出現在高山、高原，屬於高地氣候；氣候圖中氣溫最低的 (C) 是高地氣候。", "rep": false, "img": "g3-q213", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-214", "no": 214, "c": "e3", "src": "社會自修(3) 第 49 題 會考試題範例 第 1 題", "st": "自修", "ctx": "", "fig": "", "q": "2014 年世界上只有 5% 的人口居住在右圖中的深灰色區域；而相同數量的人口則居住在圖中黑色區域。小齊想要在地圖上的淺灰色區域，以圓圈標示另一個人口數量最接近的範圍，則他標示在下列何地最為適宜？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "黑色區域在南亞（印度、孟加拉），約 3.5 億人；淺灰色區域中，人口數量最接近的是中國東部的丁。", "rep": false, "img": "g3-q214", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-215", "no": 215, "c": "e8", "src": "社會自修(3) 第 49 題 會考試題範例 第 2 題", "st": "自修", "ctx": "", "fig": "表：0～14 歲比例——1953 年 36.28%、1964 年 40.69%、1982 年 33.59%、1990 年 27.69%、2000 年 22.89%、2010 年 16.60%、2020 年 17.95%；65 歲以上——4.41%、3.56%、4.91%、5.57%、6.96%、8.87%、13.50%", "q": "下表為中國不同年份的人口普查部分資料。觀察表中幼年人口比例的變動，下列何者最可能是造成 2010 到 2020 年微幅變化的原因之一？", "o": ["開放生育第二胎", "實施一胎化政策", "重男輕女觀念式微", "嚴格限制人口移入"], "a": 0, "e": "2010 到 2020 年幼年人口比例微幅回升，是因為開放生育第二胎。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-216", "no": 216, "c": "e8", "src": "社會自修(3) 第 49 題 會考試題範例 第 3 題", "st": "自修", "ctx": "", "fig": "表：甲 1949 年 鼓勵生育；乙 1960 年 提倡晚婚；丙 1979 年 一胎化；丁 2015 年 開放二胎", "q": "右表為中國在不同時間提出的人口政策，以因應各階段之需。其中哪一年提出的政策，其目標之一是為了因應老年人口比例逐漸上升所造成的高齡化問題？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "2015 年開放二胎（丁）是為了因應高齡化。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-217", "no": 217, "c": "e8", "src": "社會自修(3) 第 50 頁 選擇題 第 1 題", "st": "自修", "ctx": "", "fig": "", "q": "2015 年 10 月，中國政府中止一胎化政策，開放生育二胎，甚至在 2021 年通過三孩政策。上述政策大轉變的主要原因為何？", "o": ["死亡率偏高", "人口高齡化", "消費市場萎縮", "教育程度不佳"], "a": 1, "e": "開放二胎、三孩，主要是因為人口高齡化。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-218", "no": 218, "c": "e3", "src": "社會自修(3) 第 50 頁 選擇題 第 2 題", "st": "自修", "ctx": "", "fig": "表：界線以東——土地面積 43%、人口 94%；界線以西——土地面積 57%、人口 6%", "q": "中國的人口分布以黑河與騰衝連線為分界，表(一)為此連線兩側的土地面積及人口比例。請問：此連線兩側呈現出下列哪一項特色？", "o": ["連線以東農業發達，人口密度高，但活動空間有限", "連線以東移出率較高，使人口社會增加率較低", "連線以西因人口外流，勞力不足，以牧業為主", "連線以西因土地面積較大，環境負載力較高"], "a": 0, "e": "連線以東人口 94% 擠在 43% 的土地上，農業發達、密度高，但活動空間有限。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-219", "no": 219, "c": "e3", "src": "社會自修(3) 第 50 頁 選擇題 第 3 題", "st": "自修", "ctx": "", "fig": "", "q": "中國行政區面積相差甚大，西北的新疆、青海等面積較大，東南的福建、浙江等面積較小。造成上述行政區面積不同的最直接因素為何？", "o": ["人口密度不同", "交通發展有異", "地形類型有別", "氣候特徵不同"], "a": 0, "e": "行政區劃分會考慮人口，人口密度高的地方行政區較小，密度低的地方行政區較大。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-220", "no": 220, "c": "e1", "src": "社會自修(3) 第 50 頁 選擇題 第 4 題", "st": "自修", "ctx": "", "fig": "", "q": "郭董到中國河北省投資，時常在當地巡視廠房，每日均在附近餐館用餐。他發現北方人相當喜愛吃麵食類食品，這和當地盛產何種作物的關係最大？", "o": ["稻米", "玉米", "小米", "小麥"], "a": 3, "e": "河北在華北，屬於旱田區，盛產小麥，所以愛吃麵食。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-221", "no": 221, "c": "e3", "src": "社會自修(3) 第 51 頁 選擇題 第 5 題", "st": "自修", "ctx": "", "fig": "", "q": "中國的疆域廣闊，但人口分布極度不平均。造成上述地理現象的產生，與下列哪些關係密切？", "o": ["地形與氣候", "人民生活習慣", "全球暖化", "宗教信仰"], "a": 0, "e": "人口分布不均主要受地形與氣候影響。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-222", "no": 222, "c": "e3", "src": "社會自修(3) 第 51 頁 選擇題 第 6 題", "st": "自修", "ctx": "", "fig": "", "q": "若要在簡易的中國地圖上呈現人口分布的疏密，應選用下列哪張圖？", "o": ["西「密」、東「疏」（直線）", "北「密」、南「疏」", "西「密」、東「疏」（曲線）", "西北「疏」、東南「密」"], "a": 3, "e": "中國人口東南密、西北疏，選西北標「疏」、東南標「密」的 (D)。", "rep": false, "img": "g3-q222", "imgnote": "", "fh": "", "maps": ["g3-map-pop"], "chk": ""}, {"id": "g3-223", "no": 223, "c": "e5", "src": "社會自修(3) 第 51 頁 選擇題 第 7 題", "st": "自修", "ctx": "", "fig": "", "q": "當移民者將原鄉文化帶到移居地，可以稱為下列何者？", "o": ["文化隔閡", "文化創新", "文化認同", "文化擴散"], "a": 3, "e": "把原鄉文化帶到移居地，稱為文化擴散。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-224", "no": 224, "c": "e3", "src": "社會自修(3) 第 51 頁 選擇題 第 8 題", "st": "自修", "ctx": "", "fig": "", "q": "2024 年，中國人口密度最高的都市為廣東省深圳市，其人口密度高達 7,173 人／km²。此外，人口密度高的都市主要集中在長江三角洲、珠江三角洲和環渤海等地區。下列何者並非上述地區人口密度高的主因？", "o": ["地勢多為低平", "氣候溫暖潮溼", "開放生育三胎", "交通具有優勢"], "a": 2, "e": "三角洲人口密度高是因為地勢低平、氣候溫溼、交通便利；開放三胎不是原因。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-225", "no": 225, "c": "e1", "src": "社會自修(3) 第 51 頁 選擇題 第 9 題", "st": "自修", "ctx": "", "fig": "", "q": "圖(一)為中國主要的糧食作物分布圖，圖中 A、B 兩作物分別為何？", "o": ["水稻、小麥", "小麥、水稻", "大豆、水稻", "小麥、甘蔗"], "a": 1, "e": "A 在秦嶺淮河以北是小麥，B 在以南是水稻。", "rep": false, "img": "g3-q225", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-226", "no": 226, "c": "e5", "src": "社會自修(3) 第 51 頁 選擇題 第 10 題", "st": "自修", "ctx": "", "fig": "", "q": "2024 年 2 月，馬來西亞政府宣布將華人傳統美食「肉骨茶」列為國家美食遺產，一度在國會上引發爭論，但旅遊部門官員表示此次國家美食的遴選是從文化遺產角度出發，不應受宗教與種族所限制。上述現象是華人將原鄉的飲食文化融入東南亞，可用下列何者解釋？", "o": ["文化創新", "文化擴散", "文化傳承", "文化景觀"], "a": 1, "e": "華人把家鄉飲食帶到馬來西亞，是文化擴散。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-227", "no": 227, "c": "e4", "src": "社會自修(3) 第 51 頁 選擇題 第 11 題", "st": "自修", "ctx": "", "fig": "", "q": "圖(二)為近年中國人口數統計圖，根據圖中數據判斷，中國較容易面臨到下列何項問題？", "o": ["人口數量超過環境負荷", "人口在空間上分布不均", "人力資源素質普遍不佳", "文化擴散速度持續加快"], "a": 0, "e": "圖中人口總數已達 14.1 億，人口數量龐大，較容易超過環境負荷。", "rep": false, "img": "g3-q227", "imgnote": "", "fh": "", "maps": ["g3-map-popstat"], "chk": "自修沒有附答案，本題答案依題意判斷"}, {"id": "g3-228", "no": 228, "c": "e6", "src": "社會自修(3) 第 52 頁 選擇題 第 12 題", "st": "自修", "ctx": "", "fig": "", "q": "近年來，中國經常出現因父母過分溺愛子女，導致子女出現是非不分的問題產生；某些地區的學齡兒童成為「黑戶子女」，無法接受教育。造成上述社會問題主要是因為中國實施哪一項政策？", "o": ["一胎化政策", "推廣男女一樣好", "三孩政策", "經濟改革開放"], "a": 0, "e": "一胎化下獨生子女被溺愛，超生的孩子不敢報戶口成為黑戶。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-229", "no": 229, "c": "e2", "src": "社會自修(3) 第 52 頁 選擇題 第 13 題", "st": "自修", "ctx": "", "fig": "", "q": "中國各地的居民為了適應不同的地形與氣候，傳統維生方式通常因地制宜。下列何地多採逐水草移動的游牧方式？", "o": ["青藏高原", "東北平原", "秦嶺、淮河一帶", "新疆地區"], "a": 3, "e": "新疆氣候乾燥，牧民逐水草而居，採游牧。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-230", "no": 230, "c": "e1", "src": "社會自修(3) 第 52 頁 精熟活用 第 14 題", "st": "自修", "ctx": "", "fig": "", "q": "圖(三)是昔日中國農牧業的分區，受到自然環境影響，圖中 Ⅰ、Ⅱ 兩區的傳統維生方式有明顯的差異。關於圖中兩分區的傳統維生方式，下列何者正確？", "o": ["圖中 Ⅰ 區多為旱田；Ⅱ 區多為水田", "圖中 Ⅰ 區多種稻米；Ⅱ 區多種小麥", "圖中 Ⅰ 區在綠洲處才能種植農作物", "圖中 Ⅱ 區在綠洲處才能種植農作物"], "a": 0, "e": "Ⅰ 在秦嶺淮河以北多旱田，Ⅱ 在以南多水田。", "rep": true, "img": "g3-q230", "imgnote": "", "fh": "", "maps": ["g3-map-agri"], "chk": ""}, {"id": "g3-231", "no": 231, "c": "e5", "src": "社會自修(3) 第 52 頁 精熟活用 第 15 題", "st": "自修", "ctx": "", "fig": "", "q": "泰國曼谷的唐人街被稱為東南亞地區最大的華人文化集中區，唐人街頭的美食也多以潮汕（廣東）料理為主。若依中國人口遷移的歷程判斷，此料理最可能源自於中國何處？", "o": ["西北內陸", "西南內陸", "東南沿海", "東北沿海"], "a": 2, "e": "潮汕在廣東，是東南沿海。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-232", "no": 232, "c": "e4", "src": "社會自修(3) 第 52 頁 精熟活用 第 16 題", "st": "自修", "ctx": "", "fig": "", "q": "中國人口分布極不平均，下列為四個地區的氣候圖資料，其中哪一個地區的環境負載力最低？", "o": ["年雨量 312mm", "年雨量 1,652mm", "年雨量 36mm", "年雨量 524mm"], "a": 2, "e": "(C) 年雨量只有 36mm，非常乾燥，環境負載力最低。", "rep": true, "img": "g3-q232", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-233", "no": 233, "c": "e5", "src": "社會自修(3) 第 52 頁 精熟活用 第 17 題", "st": "自修", "ctx": "", "fig": "", "q": "聯合國稱 2017 年跨國移民的規模已達 2.5 億人，下列何者屬於移民者將原鄉文化帶到移居地的現象？", "o": ["新型冠狀病毒傳播", "臺灣麵食料理盛行", "舉辦萬人相親大會", "內蒙古高原蒙古包"], "a": 1, "e": "臺灣麵食是移民從中國北方帶來的，屬於文化擴散。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-234", "no": 234, "c": "e6", "src": "社會自修(3) 第 53 頁 精熟活用 第 18 題", "st": "自修", "ctx": "", "fig": "表(二)：可耕地總面積——中國 108,862,000 公頃、加拿大 38,259,000 公頃；人均可耕地——中國 0.08 公頃／人、加拿大 1.00 公頃／人", "q": "表(二)為 2021 年中國與加拿大的可耕地相關統計資料，表中人均可耕地面積數據產生差距的主因為何？", "o": ["人口總數", "地理位置", "產業發展", "市場需求"], "a": 0, "e": "中國人口總數太多，平均每人分到的耕地就很少。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-235", "no": 235, "c": "e1", "src": "社會自修(3) 第 53 頁 精熟活用 第 19 題", "st": "自修", "ctx": "", "fig": "", "q": "圖(四)中的甲區除了有眾多的漢族人口，也有一些少數民族，此區少數民族因深受自然環境影響，其主要傳統生活方式為何？", "o": ["伐林", "採礦", "農耕", "畜牧"], "a": 2, "e": "甲在東南部季風區，雨量多，少數民族也以農耕為主。", "rep": false, "img": "g3-q235", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-236", "no": 236, "c": "e8", "src": "社會自修(3) 第 53 頁 精熟活用 第 20 題", "st": "自修", "ctx": "", "fig": "", "q": "2000 年時，當時的中國達高齡化社會標準；2023 年，更是已邁入高齡社會，老年人口約占總人口 16%。上述現象較可能與下列何者最有關係？", "o": ["多年來執行一胎化政策", "社會福利偏重老年人口", "壯年人口大量移居海外", "第一級產業人口逐年增加"], "a": 0, "e": "一胎化使幼年人口減少，中國快速高齡化。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-237", "no": 237, "c": "e6", "src": "社會自修(3) 第 53 頁 精熟活用 第 21 題", "st": "自修", "ctx": "", "fig": "", "q": "自 1979 年中國實施一胎化政策，每年人口總數仍有微幅增加的現象，但根據聯合國統計數據，在 2023 年 4 月起的人口總數少於印度。上述提到中國人口總數仍有一段時間呈現微幅增加，此現象代表下列何者？", "o": ["糧食供應充足", "人口素質不均", "人口增加率 > 0", "社會增加率 < 0"], "a": 2, "e": "人口總數仍在增加，表示人口增加率大於 0。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-238", "no": 238, "c": "e4", "src": "社會自修(3) 第 53 頁 精熟活用 第 22 題", "st": "自修", "ctx": "", "fig": "", "q": "環境負載力是指生活環境所能供養生物數量的能力，及分解穢物的能力。依此判斷，下列哪一地理區的環境負載力最低？", "o": ["四川盆地", "華北平原", "塔里木盆地", "長江中下游平原"], "a": 2, "e": "塔里木盆地在西北乾燥區，環境負載力最低。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-239", "no": 239, "c": "e8", "src": "社會自修(3) 第 53 頁 精熟活用 第 23 題", "st": "自修", "ctx": "", "fig": "", "q": "圖(五)是 1980 年和 2020 年中國人口組成變化。僅根據圖中內容判斷，中國較可能多增設下列何種機構？", "o": ["托兒所", "補習班", "大型遊樂場", "老人安養院"], "a": 3, "e": "老年人口比例由 2.5% 增加到 12.0%，需要更多老人安養院。", "rep": false, "img": "g3-q239", "imgnote": "", "fh": "", "maps": ["g3-map-pyramid"], "chk": ""}, {"id": "g3-240", "no": 240, "c": "e6", "src": "社會自修(3) 第 53 頁 精熟活用 第 24 題", "st": "自修", "ctx": "", "fig": "", "q": "中國於 1979 年起實施一胎化政策，下列何者為此政策直接造成的影響？", "o": ["人口成長率增加", "人口性別比平衡", "自然增加率減少", "社會增加率減少"], "a": 2, "e": "一胎化直接造成出生率下降，自然增加率減少。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-241", "no": 241, "c": "e7", "src": "社會自修(3) 第 54 頁 精熟活用 第 25 題", "st": "自修", "ctx": "", "fig": "", "q": "圖(六)為 2024 年中國與世界新生兒性別比圖，依圖中統計數據判斷，下列何者正確？", "o": ["中國嬰兒性別比失衡情形嚴重", "中國男嬰的死亡機率較女嬰低", "中國男嬰的平均壽命較女嬰高", "中國男嬰人數：女嬰人數＝100：109"], "a": 0, "e": "中國新生兒性別比 109，遠高於正常範圍，失衡嚴重；109 表示女：男＝100：109。", "rep": false, "img": "g3-map-sex", "imgnote": "附圖以講義〈新生兒性別比圖〉代替", "fh": "", "maps": ["g3-map-sex"], "chk": ""}, {"id": "g3-242", "no": 242, "c": "e8", "src": "社會自修(3) 第 54 頁 統整應用題組 第 1 題", "st": "自修", "ctx": "", "fig": "", "q": "中國人口老化速度十分驚人。2000 年，中國老年人口占總人口比例首次超過 7%，開始進入高齡化社會，僅花了 22 年，就達到 14%。同樣的比例，法國花了 115 年，美國花了 72 年。到了 2040 年左右，中國老年人口將達到 4 億人，約占全國總人口的 30%。造成文中中國社會快速高齡化的原因，可能與下列何者最有關聯？", "o": ["老人社會福利政策完善", "國民所得金額逐年增加", "人口成長速度非常快速", "幼年人口比例明顯減少"], "a": 3, "e": "幼年人口比例明顯減少（一胎化），老年人口比例才快速上升。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-243", "no": 243, "c": "e8", "src": "社會自修(3) 第 54 頁 統整應用題組 第 2 題", "st": "自修", "ctx": "中國人口老化速度十分驚人。2000 年，中國老年人口占總人口比例首次超過 7%，開始進入高齡化社會，僅花了 22 年，就達到 14%。同樣的比例，法國花了 115 年，美國花了 72 年。到了 2040 年左右，中國老年人口將達到 4 億人，約占全國總人口的 30%。", "fig": "", "q": "針對上文中所提到的現象，下列哪些是未來中國政府需要面對的問題？ (甲)勞動力過剩 (乙)提升幼兒教育的素質 (丙)扶養比的增加 (丁)醫療及社福預算的增加", "o": ["甲丁", "乙丙", "乙丁", "丙丁"], "a": 3, "e": "高齡化會使扶養比增加（丙），醫療及社福預算增加（丁）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-244", "no": 244, "c": "e6", "src": "社會自修(3) 第 54 頁 統整應用題組 第 3 題", "st": "自修", "ctx": "中國人口老化速度十分驚人。2000 年，中國老年人口占總人口比例首次超過 7%，開始進入高齡化社會，僅花了 22 年，就達到 14%。同樣的比例，法國花了 115 年，美國花了 72 年。到了 2040 年左右，中國老年人口將達到 4 億人，約占全國總人口的 30%。", "fig": "", "q": "上文中提及到了 2040 年，預估中國老年人口將達到 4 億人，約占中國總人口的 30%。此現象與下列哪一原因相關？", "o": ["性別比例失衡", "人口分布不均", "人口總數龐大", "晚婚現象普遍"], "a": 2, "e": "中國人口總數龐大，老年人口比例 30% 就達 4 億人。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-245", "no": 245, "c": "e6", "src": "社會自修(3) 第 55 頁 統整應用題組 第 4 題", "st": "自修", "ctx": "", "fig": "", "q": "計畫生育是中國的人口控制政策，1979 年起提倡晚婚晚育，限制生育。上文中提到自 1979 年起所實施的人口控制政策，其名稱為何？", "o": ["一胎化政策", "二孩政策", "三孩政策", "鼓勵生育"], "a": 0, "e": "1979 年起的人口控制政策是一胎化政策。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-246", "no": 246, "c": "e6", "src": "社會自修(3) 第 55 頁 統整應用題組 第 5 題", "st": "自修", "ctx": "中國人口老化速度十分驚人。2000 年，中國老年人口占總人口比例首次超過 7%，開始進入高齡化社會，僅花了 22 年，就達到 14%。同樣的比例，法國花了 115 年，美國花了 72 年。到了 2040 年左右，中國老年人口將達到 4 億人，約占全國總人口的 30%。", "fig": "", "q": "中國自 1979 年實施人口控制政策，然而實施後總人口增加數仍高，至今仍是世界之冠，最主要的原因為何？", "o": ["糧食供應充足", "人口素質不均", "原有人口總數多", "城鄉人口流動量大"], "a": 2, "e": "雖然實施人口控制，但原有人口總數多，增加的人數仍多。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-247", "no": 247, "c": "e8", "src": "社會自修(3) 第 55 頁 統整應用題組 第 6 題", "st": "自修", "ctx": "中國人口老化速度十分驚人。2000 年，中國老年人口占總人口比例首次超過 7%，開始進入高齡化社會，僅花了 22 年，就達到 14%。同樣的比例，法國花了 115 年，美國花了 72 年。到了 2040 年左右，中國老年人口將達到 4 億人，約占全國總人口的 30%。", "fig": "", "q": "中國長時間實施人口控制政策，2013 年起逐步調整完善的生育政策，主要是在促進下列哪項目的？", "o": ["福利制度完善", "社會治安良好", "區域發展差距縮小", "人口長期均衡發展"], "a": 3, "e": "調整生育政策是為了讓人口長期均衡發展，避免少子化、高齡化。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-248", "no": 248, "c": "e7", "src": "社會自修(3) 第 56 頁 閱讀素養評量 第 1 題", "st": "自修", "ctx": "", "fig": "", "q": "中國人口普查預測，2020 年 20～45 歲的男性比女性多 3,000 萬人，其中又以農村地區最為嚴重。依上文內容判斷，2020 年中國農村聚落的性別比，應為下列何者？", "o": ["性別比 > 100", "性別比 < 100", "性別比 ＝ 100", "性別比 ＝ 3000"], "a": 0, "e": "男比女多，性別比（男÷女×100）大於 100。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-249", "no": 249, "c": "e7", "src": "社會自修(3) 第 56 頁 閱讀素養評量 第 2 題", "st": "自修", "ctx": "中國人口普查預測，2020 年 20～45 歲的男性比女性多 3,000 萬人，其中又以農村地區最為嚴重。", "fig": "", "q": "上文中提及的新娘買賣與光棍村問題，其源頭多與中國曾經實施的哪項政策有關？", "o": ["環境負載力低", "一胎化政策", "文化擴散", "就業機會不足"], "a": 1, "e": "新娘買賣與光棍村問題源自一胎化政策加上重男輕女。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-250", "no": 250, "c": "e7", "src": "社會自修(3) 第 56 頁 閱讀素養評量 第 3 題", "st": "自修", "ctx": "中國人口普查預測，2020 年 20～45 歲的男性比女性多 3,000 萬人，其中又以農村地區最為嚴重。", "fig": "", "q": "上文中提及的中國男女嬰人數差距，與何種傳統觀念有關？", "o": ["重男輕女", "崇尚多子", "敬老尊賢", "女力崛起"], "a": 0, "e": "男女嬰人數差距與重男輕女的傳統觀念有關。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-m1", "no": null, "c": "e8", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "中國在 2000 年邁入高齡化社會，2021 年邁入高齡社會。「高齡社會」是指老年人口占總人口比例達多少？", "o": ["7%", "14%", "20%", "30%"], "a": 1, "e": "65 歲以上占 7% 為高齡化社會，14% 為高齡社會，20% 為超高齡社會。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-m2", "no": null, "c": "e8", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "中國人口快速高齡化，最主要的兩個原因是什麼？", "o": ["戰爭與饑荒", "一胎化政策與醫療衛生進步", "大量移民移入與經濟衰退", "重男輕女與晚婚"], "a": 1, "e": "一胎化使幼年人口減少，醫療進步讓壽命延長，老年人口比例快速上升。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-m3", "no": null, "c": "e1", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "中國的「農牧分界」與「水田旱田分界」，依序大致是哪兩條線？", "o": ["年雨量 500mm 線；秦嶺、淮河", "秦嶺、淮河；年雨量 500mm 線", "黑河—騰衝線；年雨量 250mm 線", "一月 0℃ 線；黑河—騰衝線"], "a": 0, "e": "500mm 等雨量線分東農西牧；秦嶺、淮河（750mm、一月 0℃）分北旱田、南水田。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-m4", "no": null, "c": "e1", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "小美到秦嶺、淮河以北的華北平原旅行，最可能看到下列哪一個景象？", "o": ["水牛在水田犁田", "金黃的麥田", "牧民山牧季移", "綠洲旁的葡萄園"], "a": 1, "e": "秦嶺、淮河以北是旱田區，以小麥為主，耕牛多為黃牛。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-m5", "no": null, "c": "e6", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "中國 1979 年實施一胎化政策，最直接的影響是什麼？", "o": ["出生率下降", "死亡率上升", "移出人口增加", "性別比下降"], "a": 0, "e": "一胎化限制每對夫婦只生一胎，最直接的影響是出生率下降，自然增加率跟著下降。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-m6", "no": null, "c": "e6", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "一胎化實施後，自然增加率雖然下降，但每年增加的人口仍有數百萬人，主要原因是？", "o": ["移民大量移入", "人口基數龐大", "死亡率持續上升", "社會增加率很高"], "a": 1, "e": "人口總數非常大，即使增加率低，乘起來每年增加的人數仍然很多。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-m7", "no": null, "c": "e5", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "明清時期，中國哪一地區的居民大量移往臺灣與東南亞？", "o": ["東北", "華北", "東南沿海（福建、廣東）", "西北內陸"], "a": 2, "e": "福建、廣東山多平原少、人口增加，居民渡海到臺灣與東南亞謀生。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-m8", "no": null, "c": "e5", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "下列哪一個例子屬於「文化擴散」？", "o": ["臺灣颱風季節停班停課", "新加坡華人過農曆新年、拜媽祖", "日本發生地震", "歐洲人口老化"], "a": 1, "e": "華人移民把原鄉的節慶與信仰帶到移居地，就是文化擴散。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-m9", "no": null, "c": "e3", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "黑河—騰衝線的兩個端點，分別位於中國哪兩個省分？", "o": ["黑龍江省、雲南省", "吉林省、四川省", "黑龍江省、西藏自治區", "內蒙古、廣西"], "a": 0, "e": "黑河在黑龍江省（東北），騰衝在雲南省（西南）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-m10", "no": null, "c": "e3", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "黑河—騰衝線以東，面積與人口比例大約是多少？", "o": ["面積 57%、人口 6%", "面積 43%、人口 94%", "面積 50%、人口 50%", "面積 94%、人口 43%"], "a": 1, "e": "東半部面積只占 43%，卻住了約 94% 的人口。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-m11", "no": null, "c": "e7", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "中國新生兒性別比為 109，代表什麼意思？", "o": ["每 100 名男嬰對 109 名女嬰", "每 100 名女嬰對 109 名男嬰", "男嬰占 109%", "女嬰比男嬰多 9 人"], "a": 1, "e": "性別比＝男÷女×100，109 表示每 100 名女嬰對應 109 名男嬰。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-m12", "no": null, "c": "e7", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "中國出現大量「光棍」，主要是哪兩個因素造成的？", "o": ["重男輕女觀念與一胎化政策", "醫療進步與高齡化", "人口外移與都市化", "文化擴散與移民"], "a": 0, "e": "只能生一胎又重男輕女，男嬰比例偏高，長大後男多女少，形成光棍問題。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-m13", "no": null, "c": "e2", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "「春天把牲畜趕到山上吃草，秋天再趕下山避冬」，這種畜牧方式叫什麼？主要在哪裡？", "o": ["游牧；新疆沙漠邊緣", "放牧；內蒙古東部", "山牧季移；青藏高原", "欄牧；華北平原"], "a": 2, "e": "依海拔高低的季節性移動是山牧季移，出現在青藏高原、天山等高山地區。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g3-m14", "no": null, "c": "e2", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "內蒙古高原東部多放牧、西部多游牧，主要差別在於？", "o": ["地勢高低", "降水多寡", "距海遠近", "技術好壞"], "a": 1, "e": "東部降水較多、水草較豐，可以定居放牧；西部較乾，必須逐水草游牧。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}], "extras": [{"id": "compare", "title": "易混淆比較", "html": "<h3>1. 中國東半部 vs. 西半部 人文與自然環境對照表</h3><div class=\"tbl\"><table><thead><tr><th>比較項目</th><th>東半部地區</th><th>西半部地區</th></tr></thead><tbody><tr><td><b>劃分界線</b></td><td><b>黑河—騰衝線以東</b></td><td><b>黑河—騰衝線以西</b></td></tr><tr><td><b>土地面積比例</b></td><td>約 <b>43%</b>（較小）</td><td>約 <b>57%</b>（較大）</td></tr><tr><td><b>全國人口比例</b></td><td>約 <b>94%</b>（極稠密）</td><td>約 <b>6%</b>（極稀疏）</td></tr><tr><td><b>主要地形類型</b></td><td>平原、丘陵為主（地勢第三階梯）</td><td>高原、盆地、高山為主（第一、二階梯）</td></tr><tr><td><b>氣候特徵</b></td><td>季風氣候區，年降水量大於 500 mm，溫暖濕潤</td><td>乾燥氣候區與高地氣候區，降水稀少（小於 500 mm）</td></tr><tr><td><b>傳統農業型態</b></td><td><b>農業區</b>（南水田、北旱田）</td><td><b>畜牧區</b>为主（放牧、游牧、山牧季移），綠洲與河谷有灌溉農業</td></tr><tr><td><b>環境負載力</b></td><td><b>高</b>（水土豐沃，可供養大量人口）</td><td><b>低</b>（生態脆弱、水源匱乏，環境承載極限低）</td></tr></tbody></table></div><h3>2. 東部農業區內部比較：秦嶺—淮河以北 vs. 以南</h3><div class=\"tbl\"><table><thead><tr><th>比較項目</th><th>秦嶺—淮河以北（北方）</th><th>秦嶺—淮河以南（南方）</th></tr></thead><tbody><tr><td><b>1 月均溫分界</b></td><td><b>$&lt; 0^\\circ\\text{C}$</b>（冬季河川會結冰）</td><td><b>$&gt; 0^\\circ\\text{C}$</b>（冬季河川不結冰）</td></tr><tr><td><b>年降水量</b></td><td><b>$&lt; 750\\text{ mm}$</b>（多在 500～750 mm 間）</td><td><b>$&gt; 750\\text{ mm}$</b>（普遍大於 1,000 mm）</td></tr><tr><td><b>耕地類型</b></td><td><b>旱田</b>為主</td><td><b>水田</b>為主</td></tr><tr><td><b>主要糧食作物</b></td><td><b>小麥</b>、高粱、玉米</td><td><b>水稻</b></td></tr><tr><td><b>耕作熟期</b></td><td>一年一熟至兩年三熟（生長季較短）</td><td>一年兩熟至一年三熟（生長季長）</td></tr><tr><td><b>傳統生活用牲畜</b></td><td>黃牛（適合旱田牽引、耐寒）</td><td>水牛（適合水田耕耘作業）</td></tr></tbody></table></div><h3>3. 西部畜牧業三大型態對照表</h3><div class=\"tbl\"><table><thead><tr><th>畜牧型態</th><th>經營方式與動態特徵</th><th>氣候與地理分布區域</th><th>代表牲畜／適應機制</th></tr></thead><tbody><tr><td><b>放牧</b></td><td>定居於固定牧場，牲畜於圍欄或草場就地啃食</td><td>降水相對較多、水草豐美的<b>內蒙古高原東側</b></td><td>馬、牛、綿羊</td></tr><tr><td><b>游牧</b></td><td>水草有限，牧民攜帶帳篷（蒙古包）<b>逐水草水平移動</b></td><td>氣候乾旱乾燥的<b>新疆沙漠邊緣、內蒙古高原西側</b></td><td>駱駝、山羊、綿羊</td></tr><tr><td><b>山牧季移</b></td><td><b>垂直季節移動</b>：春夏季上山吃草，秋冬季下山避冬</td><td>地形起伏大、垂直氣候明顯的<b>青藏高原、天山山脈</b></td><td><b>犛牛</b>（高原之舟）、藏羊</td></tr></tbody></table></div><h3>4. 中國當代人口政策演變對照表</h3><div class=\"tbl\"><table><thead><tr><th>政策階段</th><th>實施年代</th><th>主要核心內容</th><th>實施背景與核心目的</th></tr></thead><tbody><tr><td><b>計畫生育（一胎化政策）</b></td><td>1979～2015 年</td><td>嚴格規定一對夫妻只能生育一個孩子</td><td>控制人口總數過快暴增，減輕環境負載與資源短缺壓力</td></tr><tr><td><b>全面二孩政策</b></td><td>2015～2021 年</td><td>全面結束一胎化，允許所有夫妻生育第二個子女</td><td>舒緩因一胎化帶來的少子化、高齡化與勞動力短缺問題</td></tr><tr><td><b>三孩政策</b></td><td>2021 年起推行至今</td><td>允許生育三個子女，配套提供教育、住房、托育與稅賦減免補貼</td><td>因應出生率持續走低、超低生育率及人口即將呈現負成長的困境</td></tr></tbody></table></div>"}, {"id": "timeline", "title": "人口政策演進", "html": "<h3>中國近現代人口轉型與社會結構變遷流程</h3><div class=\"tbl\"><table><thead><tr><th>年代時期</th><th>人口政策／社會事件</th><th>人口現象與結構重大特點</th></tr></thead><tbody><tr><td><b>明清時期</b></td><td>東南沿海人口激增、耕地不足</td><td>大批東南沿海居民渡海遷徙至臺灣及東南亞（下南洋），造成大規模文化擴散。</td></tr><tr><td><b>1949 年建國初</b></td><td>戰後復甦鼓勵生育（人多好辦事）</td><td>醫療進步與死亡率下降，人口總數爆發性成長。</td></tr><tr><td><b>1979 年</b></td><td><b>實施「一胎化政策」</b></td><td>自然增加率快速降至 12‰ 以下；出生性別比嚴重失衡，男嬰比例長期大幅高於女嬰。</td></tr><tr><td><b>2000 年</b></td><td>65 歲以上人口占比突破 7%</td><td><b>正式邁入「高齡化社會」</b>；壯年人口處於最高峰，享受人口紅利帶動經濟起飛。</td></tr><tr><td><b>2015 年</b></td><td><b>宣布廢除一胎化，推行「全面二孩」</b></td><td>面臨幼年人口比率過低（少子化）與青壯年勞動力萎縮危機，政策全面轉向。</td></tr><tr><td><b>2021 年</b></td><td>65 歲以上人口占比突破 14%；<b>通過「三孩政策」</b></td><td><b>正式進入「高齡社會」</b>；人口自然增加率逼近於 0 並出現負成長趨勢，人口總數被印度超越。</td></tr></tbody></table></div>"}, {"id": "charts", "title": "圖表判讀", "html": "<h3>1. 《中國人口分布圖（黑河—騰衝線）》</h3><figure class=\"cimg\"><img src=\"img/g3-map-pop.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>中國人口分布圖（黑河—騰衝線）</figcaption></figure><p class=\"li\"><b>圖表名稱</b>：《中國人口密度分布與黑河—騰衝分界線示意圖》。</p><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">1. 連接東北黑龍江省「黑河」與西南雲南省「騰衝」的斜線，將中國分為西北與東南兩大半部。</p><p class=\"li sub\">2. 線以東的東半部，點密度極高（密密麻麻），面積僅 43% 卻住有 94% 人口。</p><p class=\"li sub\">3. 線以西的西半部，大部分區域為大片留白，面積占 57% 卻僅住 6% 人口，點僅零星分布於天山南北山麓綠洲與河谷地帶。</p><p class=\"li\"><b>常見判讀方式</b>：考試常遮蓋兩端地名考「黑河」與「騰衝」的省分與代號；或給出四張輪廓圖，要求選擇「東密西疏」正確呈現者（選東半部標「密」、西半部標「疏」者）。</p><h3>2. 《中國傳統農牧業分布與等雨線圖》</h3><figure class=\"cimg\"><img src=\"img/g3-map-agri.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>中國農牧業分布與等雨量線</figcaption></figure><p class=\"li\"><b>圖表名稱</b>：《中國農牧業分區與年降水量等雨線疊合圖》。</p><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">1. <b>農牧分界線</b>：與 <b>年降水量 500 mm 等雨線</b> 大致吻合。以東為農業區，以西為畜牧區。</p><p class=\"li sub\">2. <b>南北農業（水田／旱田）分界線</b>：與 <b>秦嶺—淮河一線</b>（即 <b>年降水量 750 mm 等雨線</b> 及 <b>一月均溫 0℃ 等溫線</b>）相符合。以北為旱田（小麥），以南為水田（水稻）。</p><p class=\"li sub\">3. 西部畜牧區內部的細分：內蒙古東部為「放牧」、內蒙古西部與新疆為「游牧」、青藏高原為「山牧季移」。</p><p class=\"li\"><b>常見判讀方式</b>：題目給予農牧界線，問其與哪條氣候分界線相符（答 500 mm 等雨線）；或問南北糧食作物差異的氣象依據（秦嶺淮河、0℃、750 mm）。</p><h3>3. 《中國人口金字塔圖的時空變遷》</h3><figure class=\"cimg\"><img src=\"img/g3-map-pyramid.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>中國人口金字塔圖（1980、2020、2040）</figcaption></figure><p class=\"li\"><b>圖表名稱</b>：《中國 1980 年、2020 年與 2040 年（推估）人口金字塔圖》。</p><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">1. <b>1980 年</b>：底部寬廣、頂部狹窄，呈「增加型（傳統型）」，幼年人口占比高達 36.2%，老年人口僅 2.5%。</p><p class=\"li sub\">2. <b>2020 年</b>：底部急劇向內收縮（受一胎化衝擊），中間壯年人口向外凸出（占 70.3% 提供人口紅利），頂部老年人口比率擴大至 12.0%，型態轉為「縮減型」。</p><p class=\"li sub\">3. <b>2040 年（推估）</b>：底部更窄（幼年僅 14.2%），65 歲以上高齡人口比例膨脹至 23.7%，形狀呈頂寬底窄的倒金字塔或燈泡形，呈現嚴重超高齡化與勞動力斷層危機。</p><p class=\"li\"><b>常見判讀方式</b>：判斷年代先後順序為由底部最寬逐步變至底部最窄；並藉由中間壯年與底部幼年比例變化，推論「撫養比先降後升」及「未來勞動人口短缺、老年安養院需求暴增」。</p><h3>4. 《中國歷年新生兒性別比變化柱狀／折線圖》</h3><figure class=\"cimg\"><img src=\"img/g3-map-sex.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>中國歷年新生兒性別比變化統計圖</figcaption></figure><p class=\"li\"><b>圖表名稱</b>：《中國與世界主要國家新生兒性別比對比圖》。</p><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">1. 正常新生兒性別比介於 102～107 之間（世界平均約 105）。</p><p class=\"li sub\">2. 中國自 1980 年代起顯著攀升，高峰時一度逼近 120，2024 年仍高達 109，遠高於世界平均及歐美各國。</p><p class=\"li\"><b>常見判讀方式</b>：若圖表顯示中國數值超過 100 甚多，代表「男多於女」；推論原因必與「重男輕女傳統觀念」加上「一胎化政策」之加乘效應有關。</p>"}, {"id": "tips", "title": "口訣與防錯", "html": "<h3>考試核心防陷阱口訣</h3><div class=\"poem\"><b>「黑河騰衝分東西，東占九四西占六；</b></div><div class=\"poem\"><b>五百雨線分農牧，放游山牧各不同；</b></div><div class=\"poem\"><b>秦嶺淮河零度線，南稻水牛北麥黃；</b></div><div class=\"poem\"><b>閩粵人稠山地狹，冒險南洋媽祖隨；</b></div><div class=\"poem\"><b>七九一胎降自然，重男輕女引光棍；</b></div><div class=\"poem\"><b>紅利消退老人增，二孩三孩急催生。」</b></div><p class=\"li\"><b>防錯關鍵 1（黑河騰衝線的配對與省分）</b>：</p><p class=\"li sub\">• <b>黑河</b>位於<b>黑龍江省</b>（東北）。</p><p class=\"li sub\">• <b>騰衝</b>位於<b>雲南省</b>（西南）。</p><p class=\"li sub\">• 易錯選項常混入「漠河」、「昆明」、「拉薩」等城市進行干擾，務必認清「黑河—騰衝」。</p><p class=\"li\"><b>防錯關鍵 2（兩大氣候等值線的意義絕不混淆）</b>：</p><p class=\"li sub\">• <b>年降水量 500 mm 等雨線</b>：區分<b>農業區（東）</b>與<b>畜牧區（西）</b>。</p><p class=\"li sub\">• <b>秦嶺—淮河線（年雨量 750 mm／1月均溫 0℃）</b>：區分農業區內部的<b>水田（南）</b>與<b>旱田（北）</b>。</p><p class=\"li\"><b>防錯關鍵 3（畜牧類型的環境判斷）</b>：</p><p class=\"li sub\">• 看到「高原垂直氣候」、「春天上山吃草、秋天下山避冬」→ 必選<b>山牧季移</b>（青藏高原、天山）。</p><p class=\"li sub\">• 看到「逐水草而居、水平移動」→ 必選<b>游牧</b>（新疆、內蒙古西部沙漠荒漠）。</p><p class=\"li\"><b>防錯關鍵 4（明清移民方向與歷史背景）</b>：</p><p class=\"li sub\">• 明清時期東南沿海居民是移向<b>臺灣</b>與<b>東南亞（南洋）</b>，絕非移向東北或西北。</p><p class=\"li sub\">• 外移的主因為「<b>地狹人稠、山多平原少、耕地不足</b>」，並非為了遊歷或政府強迫拓荒。</p><p class=\"li\"><b>防錯關鍵 5（性別比定義與數字解讀）</b>：</p><p class=\"li sub\">• 性別比公式為 男性 ÷ 女性 × 100。</p><p class=\"li sub\">• 性別比為 109 代表「每 100 名女嬰對應 109 名男嬰」，數值大於 100 即為<b>男多於女</b>（切勿看成女多於男或百分比）。</p><p class=\"li\"><b>防錯關鍵 6（人口總數 vs. 自然增加率的區別）</b>：</p><p class=\"li sub\">• 一胎化政策使中國的「<b>自然增加率</b>」大幅降低。</p><p class=\"li sub\">• 但由於中國「<b>人口母體基數龐大</b>」，每年淨增加的人口數量在過去數十年間依然相當可觀，並非一實施人口就立刻減少。</p>"}]});
